window.POEM_DB=window.POEM_DB||{};POEM_DB["song_087"]={"n":"徐积","dyn":"宋","poems":[{"t":"长春花 其一","f":"七言律诗","c":["谁言造物无偏处，独遣春光住此中。","叶里深藏云外碧，枝头常借日边红。","曾陪桃李开时雨，仍伴梧桐落后风。","费尽主人歌与酒，不教閒却卖花翁。"]},{"t":"长春花 其二","f":"七言律诗","c":["一从春色入花来，便把春阳不放回。","雪圃未容梅独占，霜篱初约菊同开。","长生洞里神仙种，万岁楼前锦绣堆。","过尽白驹都不管，绿杨红杏自相催。"]},{"t":"长春花 其三","f":"七言律诗","c":["一谢芳菲更不还，谁何娇步独盘桓。","虽于物态为难有，却是时情总易阑。","日晒香肌难避暑，雪濡粉面亦禁寒。","等閒莫使人知处，长与诗家醉后看。"]},{"t":"长春花 其四","f":"七言律诗","c":["谁与猩猩血染红，重重叠叠费春工。","应无暴物侵和气，自有深根藏暖风。","每见灵芝三秀了，回看凡艳一时空。","如环光景循将遍，又到江南梅信通。"]},{"t":"长春花 其五","f":"七言律诗","c":["枝上疏疏花启房，轻绡重锦迭为裳。","更分深浅两般色，不作寻常一面妆。","蕣有红华须斗艳，兰虽清节亦交香。","吟翁未畅先投笔，为与东君咏海棠。"]},{"t":"赠黄鲁直","f":"七言绝句","c":["不见故人弥有情，一见故人心眼明。","忘却问君船住处，夜来清梦绕西城。"]},{"t":"花下饮","f":"五言古诗","c":["我向桃花下，立饮一杯酒。","杯酒先濡须，花香随入口。","花为酒家媪，春作诗翁友。","此时酒量开，酒量添一斗。","君看陌上春，令人笑拍手。","半青篱畔草，半绿畦中韭。","闲乌下牛背，奔豚穿狗窦。","潜身猫相雀，引喙禽呼偶。","包麻邻乞火，穿桑儿饷糗。","物类虽各殊，所乐亦同有。","谁知花下情，犹能忆杨柳。","中心卒无累，外物任相揉。","余方寓之乐，自号閒人叟。"]},{"t":"哭张六","f":"五言古诗","c":["欲视目已瞑，欲语口已噤。","欲动肉已寒，欲书手已硬。","惟有心上热，惟存心中悲。","此热须臾閒，此悲无休时。","所悲孤儿寒，所悲孤儿饥。","苦苦复苦苦，此悲遂入土。"]},{"t":"醉中咏牡丹","f":"楚辞体","c":["此花未开时，美子藏深闺。","香心若无有，深浅何由知。","前日花忽开，美人放出深闺来。","春风尽日不相管，莺是郎兮蝶是媒。","谁将金钱掷西子，笑中不掩燕脂腮。","君王亲执紫金盏，太真又醉白瑶台。","此花万态不可说，莫教容易为尘埃。","我心虽然淡如水，为花一醉何辞哉。"]},{"t":"渔父乐 其三 堪画看","f":"词","c":["讨得渔竿买得船，归休何必待高年。","深浪里，乱云边，只有逍遥是水仙。"]},{"t":"渔父乐 其一","f":"词","c":["水曲山隈四五家，夕阳烟火隔芦花。","渔唱歇，醉眠斜，纶竿蓑笠是生涯。"]},{"t":"渔父乐 其四 谁学得","f":"词","c":["饱则高歌醉即眠，只知头白不知年。","江绕屋，水随船，买得风光不著钱。"]},{"t":"渔父乐 其六 君不悟","f":"词","c":["一酌村醪一曲歌，回看尘世足风波。","忧患大，是非多，纵得荣华有几何。"]},{"t":"渔父乐 其二 无一事","f":"词","c":["见说红尘罩九衢，贪名逐利各区区。","论得失，问荣枯，争似侬家占五湖。"]},{"t":"渔父乐 其五 君看取","f":"词","c":["管得江湖占得山，白云同散学云閒。","清旦出，夕阳还，不知身在画屏閒。"]},{"t":"老仙","f":"七言绝句","c":["脚踏青云身已老，访道修真恨不早。","曾见商周全盛时，不及唐虞古风好。"]},{"t":"上赵少师","f":"楚辞体","c":["义高德厚贤在躬，进荣退美光初终。","越有神明相元功，疾忧之外康宁中。","乃眷乃顾爰徂东，徒御虽寡人望雄。","其高可仰厚可宗，兹行允美江淮风。","父老相呼告儿童，三朝无事繄厥忠。","公谋公惠世所蒙，肆安于贾田安农。","温衣蔽体食饱胸，小攘大窃消奸凶。","州牢县狱囚多空，欢心和气成年丰。","汝曹虽騃念所从，汝心汝貌加爱恭。","薪蒸勿采米勿舂，亟歌屡舞驰省公。","有人昔与公车逢，汝阴颍尾洛与嵩。","山有迹兮水有踪，水之鹤兮山之松。","一朝赐号逍遥翁，马资仆费官与供。","汝曹努力吾老癃，公若再来勤筑宫。"]},{"t":"忠烈诗","f":"词","c":["在昔皇祐，蛮党交构。","聚为伏枭，起为攫兽。","出人不意，其锋甚锐。","州无敌兵，城无守备。","所在奔亡，贼势益张。","横身捍蔽，爰有晋康。","羸兵数百，摧坚沮敌。","殊死血战，气吞逆贼。","按剑一呼，眦裂吻拆。","凶焰方炽，公方虎视。","人方忧死，饱食鼾睡。","勇如项籍，哀歌恻恻，为虞姬泣。","康州不然，忘其妻息。","猛如敖曹，强梁粗豪，伏藏于桥。","康州不然，坐叱凶妖。","李陵壮夫，终降匈奴，老母何辜。","颜鲁虽贤，所守不坚，大节不全。","奇哉康州，其勇绝类。","以义配勇，其本在内。","不动如山，不倾如地。","何物可摇，何兵可制。","如令不死，社稷所恃。","如令复生，可备宿卫。","佩刀骖乘，势戟殿陛。","用之朝廷，朝廷之纲。","使当一面，胜于金汤。","无疆无界，人迹鬼方。","知有斯人，中国之光。","若斯人者，决不徇利。","肝胆可沥，头璧可碎。","生乎由是，死乎由是。","生亦可贵，死亦可贵。","死而有子，时方三岁。","死中得活，此乃天意。","使世其家，世为忠义。","子子孙孙，永不失坠。","我为此诗，激励万世。"]},{"t":"和杨掾月蚀篇","f":"词","c":["元丰之元岁戊午，斗柄斜指西南维。","月行赤道日南陆，营丘分野星虚危。","昨夕既望复今夕，盛若不损盈不亏。","安知变起在顷刻，突如有物侵其肌。","其始色变甚苍黄，须臾赤黑相合离。","良久烟焰极薰燎，一团白玉烧为灰。","黄琮苍璧不可辨，枯株死兔将安归。","孰乌其吻吞巨皿，孰丹其汗流墨池。","如食非食始为薄，有物无物不可知。","虾蟆何物敢张口，麒麟何故敢争斗。","是何星曜敢侵犯，自是其形不可久。","君不见对月数眉毛，须臾引臂不见手。","嗟吁天上之神物，乃有如此事。","所蔽至甚不可解，凶而家室亡而身。","不然借使幸而免，后世讥笑遭恶名。","君不见汉朝贾生文有馀，其心大勇其才疏。","当时如必用其术，纷纷不免危其躯。","鼌错堂堂蔽于刻，公孙规规蔽于谀。","谷永之才蔽权势，有若鹰犬供指呼。","霍光虽贤亦有蔽，何不早去显与冯子都。","刘歆致位为国师，岂若扬雄久以为大夫。","蔽于太高李膺辈，蔽于已甚陈蕃徒。","窦武不断蔽可痛，柬之不忍蔽可吁。","王允所蔽在无权，荀彧所蔽不早图。","萧瑀之蔽入于佞，王衍之蔽失之虚。","牛李虽奇蔽朋党，机云虽俊蔽附趋。","王导蔽怨杀周顗，遂良蔽诬杀刘洎。","崔浩蔽强杀其身，所蔽若此甚可畏。","我爱安世真朴忠，匿名远世归至公。","有私见求坚不许，以私求谢绝不通。","诸葛武侯为将相，心迹皎然无所枉。","有罪至亲而必诛，有功虽雠而必赏。","谢安知婿王国宝，不以身蔽能辨早。","人心自是说而服，不顾四肢与肝脑。","苻坚之师号百万，一战而北若摧槁。","我吟此篇不足录，却忆唐衢忠义哭。","古人今人何择焉，大抵人心蔽多欲。","月之所蔽惟须臾，须臾蔽去明如初。","人之所蔽何太甚，至于终身不悟不可除。","月乎月乎，明哉明哉。","善去其蔽，何速之如。","君子法之，所以改过。","贤者法之，所以知非。","勇决之徒，所以奋发。","感慨之徒，所以嘘欷。","我虽老且病，龊龊无所为。","犹能对月吟歌诗，安得慷慨之士如桓伊，把笛为予吹。"]},{"t":"大河上天章公顾子敦","f":"五言古诗","c":["万物皆有性，顺其性为大。","顺之则无变，反之则有害。","禹之治河也，浚川而掘地。","水行乎地中，其性安而遂。","因地为之防，犹恐不足制。","故附之山足，使循山而行。","山不可必得，或原阜丘陵。","水行乎两间，既固而既宁。","及将近下流，山远而地平。","渠裂为二道，河分为九形。","虽暴不得怒，虽盛不得盈。","所以顺而制，归之于沧溟。","后代蒙其业，历世六七十。","凡千有馀年，而无所决溢。","国君与世主，岂皆尽有德。","盖繇河未徙，一皆循禹迹。","河道既一徙，下涉乎战国。","水行平地上，乃堤防堙塞。","其时两堤间，实容五十里。","水既有游息，堤无所啮毁。","后世迫而坏，河役始烦促。","伐尽魏国薪，下尽淇园竹。","群官皆负薪，天子自临督。","其牲用白马，其璧用白玉。","歌辞剧辛酸，姑不至号哭。","瓠子口虽塞，宣房宫虽筑。","其后复北决，分为屯氏河。","遂不复堤塞，塞亦无如何。","两河既分流，害少而利多。","久之屯氏绝，遂独任一渠。","凡再决再塞，用延世之徒。","有天时人事，可图不可图。","有幸与不幸，数说不可诬。","其后复大决，大坏其田庐。","灌三十一县，言事者纷如。","将欲塞之耶，凡役百万夫。","费累百巨万，亦未知何如。","如此是重困，是重民叹吁。","言事者不已，亦不复塞诸。","李寻解光辈，其言不至迂。","遂任水所之，渠道自割除。","当时募水工，无一人应书。","学虽有专攻，术亦有穷欤。","诸所说河者，桓谭实主之。","但聚而为书，实无以处之。","班孟坚作志，亦无所出取。","事有甚难者，虽知无所补。","今之为河堤，与汉无甚殊。","远者无数里，近无百步馀。","两堤束其势，如缚吞舟鱼。","适足激其怒，使之逃囚拘。","又水性隐伏，有容而必居。","浸淫而灌注，日往而月徂。","埽材有腐败，土壤有浮虚。","水进而不止，正如人病躯。","病已在骨髓，医方治皮肤。","下不漏足胫，上突为背疽。","或水如雷声，或埽如人喘。","或决如山倾，或去如席卷。","如蛟龙引阵，如虎豹逃圈。","如地户开辟，如谁何生变。","如神物主之，不可得而辨。","嗟乎有如此，堤防岂能禁。","盖缘平地上，失水之本性。","而又无二渠，分九河所任。","以九合为一，所以如此甚。","今之为邑居，多在古堤内。","以诸埽准之，高于屋数倍。","以水面准之，亦高数尺外。","诸埽正如城，而土有轻脆。","民正如鱼鳖，处破湟畎浍。","被溺者常事，不溺者幸大。","又河水重浊，淀淤日以积。","又夏秋霖雨，诸水凑以入。","故有必决势，不决者盖鲜。","或决彼决此，或决近决远。","或决不可塞，或塞而复决。","或决于旦暮，或决于岁月。","或新埽苟完，或旧埽溃裂。","譬如千万钧，用一绳持挈。","必有时而败，必有处而绝。","而自决大吴，凡害几郡县。","河既北浸边，诸塘皆受患。","亡胡与逸马，熟为之隔限。","今虽甚盛时，亦防不虞变。","所以议论者，复故道为便。","故道虽已高，可复亦可为。","但恐既复后，其变不可知。","我兵学虽陋，公兵学虽奇。","我说兵之难，公亦莫我违。","河事异于兵，其难堪嘘欷。","智有不可及，力有不可施。","汲黯非不伟，所塞辄复隳。","王遵无奈何，誓死而执圭。","若与唐衢说，号哭垂涕洟。","未说穿故道，未说治故堤。","且说塞河口，所费不可推。","诸所调发者，委积与山齐。","卷埽者如云，进埽者如飞。","下埽名入川，其势忧流移。","上埽名争高，少动即势危。","万人梯急赴，两大鼓急椎。","作号声号令，用转光指麾。","其救护危急，争须臾毫釐。","又闻被灾郡，数路方荐饥。","官私无畜聚，民力俱困疲。","朝廷谋已劳，两宫食不怡。","生民仰首望，使者忘寝饥。","为之柰何乎，勿计速与迟。","事虽有坚定，议论在所持。","如一身数疾，必以先后医。","假如移所费，用以业贫民。","偿其所亡失，救其所苦辛。","或贷其田租，或享其终身。","独孤有常饩，使同室相亲。","露尸与暴骸，收敛归诸坟。","精选强明吏，处之使平均。","乡官与胥徒，欺者以重论。","如此庶几乎，可无愁怨人。","下酬更生望，上慰再造仁。","然而论议者，至今犹纷纷。","或复其故道，或因其自然。","公如决于一，勿使众议牵。","在己者有义，在命者以天。","而况行职分，而况本诚忱。","圣朝无不察，知子之赤心。","嗟余何为者，草莽且贱微。","与公本无素，一见即弗遗。","以伯兄处我，以古人相期。","小设犹致说，大事宁无辞。","年且六十一，未作沟中尸。","常恐公礼义，如投诸污泥。","岂欲为迂阔，不得已为诗。","沥吾之肝胆，但恐同儿嬉。","又恐误公事，公千万慎思。","如将从近功，即深图便宜。","如必谋久利，唯古人是希。","是询而是度，是访而是咨。","或博物君子，或宿儒老师。","或滨河野叟，或市井年耆。","或愚直夫妇，所言无蔽欺。","或老胥退兵，耳闻而目窥。","或世为水学，可与讲是非。","或博募水工，按地形高卑。","从便道穿渠，稍引河势披。","海既为大壑，汴既分一支。","如关窍疏通，脏腑病可治。","此说如何哉，但恐出于狂。","如何完障塞，如何复诸塘。","观变而待时，亦恐谋不臧。","为复有说者，且须严边防。","如魏尚守边，见称于冯唐。","如祭彤久任，使匈奴伏藏。","以车制冲突，如卫青武刚。","多置强弩手，如李广大黄。","选募如马隆，练卒如高王。","如汉置奔命，使我军势张。","短兵斫马胫，冲车乱其行。","赏不以首级，所以严部分。","大陷刀如墙，可以坚吾阵。","羊叔子以德，郭子仪以信。","光弼战河阳，挥旗令直进。","其时诸军势，如决水千仞。","杨素不用车，可汗下马拜。","仅以其身免，号哭而大败。","将帅在方略，胜却百万兵。","安边在良将，胜却筑长城。","愿子治水功，有以酬明时。","便领铁林兵，尽衣犀牛皮。","连营环绣帽，大纛随牙旗。","分金赐勇敢，藏书付偏裨。","先声义信远，下令霜风驰。","出塞有丰草，近关无马蹄。","穹庐大漠外，别部黑山西。","伐谋为上策，何用长缨羁。","本朝正明盛，以德服外夷。","使来不受献，南越回山梯。","西闭玉门关，东却高句丽。","四夷无一事，各安巢穴栖。","名将更无功，优诏勒鼎彝。","师旋作鼓吹，军容除虎貔。","银珰致郊劳，翰林严锁扉。","除书纸用麻，省吏身著绯。","公方有所念，山足江之湄。","无心入黄阁，有表辞赤墀。","乞得老来身，浩歌还会稽。","白云与绿波，无所不可之。","春风桃花坞，秋色黄菊篱。","茶篮与酒榼，壶矢兼琴棋。","烹鸡炊黍饭，可倩庞公妻。","岂无会稽老，雪夜同泛溪。","亦有二三子，棹歌相追随。","散尽橐中金，留得身上衣。","有宅是官借，无田可扶犁。","闲吟题寺观，长啸入云霓。","公得我诗后，一梦须先归。"]},{"t":"李太白杂言","f":"词","c":["噫嘻欷奇哉，自开辟以来，不知几千万馀年。","至于开元间，忽生李诗仙。","是时五星中，一星不在天。","不知何物为形容，何物为心胸。","何物为五脏，何物为喉咙，开口动舌生云风。","当时大醉骑游龙，开口向天吞玉虹。","玉虹不死蟠胸中，然后吐出光焰万丈凌虚空。","盖自有诗人以来，我未尝见大泽深山。","雪霜冰霰，晨霞夕霏。","万化千变，雷轰电掣。","花葩玉洁，青天白云，秋江晓月。","有如此之人，有如此之诗。","屈生何悴，宋玉何悲。","贾生何戚，相如何疲。","人生胡用自缧绁，当须荦荦不可羁。","乃知公是真英物，万叠秋山耸清骨。","当时杜甫亦能诗，恰如老骥追霜鹘。","戴乌纱，著宫锦，不是高歌即酣饮。","饮时独对月明中，醉来还抱清风寝。","嗟君逸气何飘飘，枉教谪下青云霄。","大抵人生有用有不用，岂可戚戚反效儿女曹。","采蟠桃于海上，寻紫芝于山腰。","吞汉武之金茎沆瀣，吹弄玉之秦楼凤箫。"]},{"t":"送程守","f":"词","c":["蜀之有眉，有山有江。","江大而浚，山形甚庞。","是生程公，为国重器。","可处大任，可决大事。","凡有措置，凡有施设。","坚不可摇，牢不可拔。","所以蜀人，号为铁塔。","维公有子，为山阳守。","所性所养，质直真厚。","维其质直，不浮不苟。","不生巧心，不为利口。","维其真厚，不矫不激。","体无邪气，面无邪色。","视其气貌，察其动静。","可知所养，可知所性。","可知其德，可知其政。","质直真厚，故不生事。","不为小数，不任小智。","以恕辅法，因法行恕。","不烦不苛，不暴不怒。","遂使斯民，如行大路。","无险可虞，无伤可虑。","肌肤以完，手足可措。","奸凶以衰，盗贼亦沮。","父母妻子，邑居田庐。","各安其故，各保其居。","为政如此，民是以和。","是以可慕，是以可歌。","不能歌者，太守之量。","可歌可传，可法可尚。","可以容众，可以任重。","无适不可，惟上所用。"]},{"t":"送李端叔","f":"词","c":["有人颇似长沙傅，得官亦望长沙去。","去时好赋楚江谣，还使风骚满江路。","便须酌酒吊三闾，正是忠魂冤愤处。","县令如今未去时，兰亭故事犹可为。","莫惜千筒万筒往，诸君方壮我已疲。","登科学究文章豪，数奇老将诗能高。","长沙县令号才吏，方将睥睨谢与曹。","凉风即是八九月，红萸黄菊花将发。","正是诗家得意时，莫学古人悲莫节。","东南美者有吴姬，红襦绣袂无所施。","把酒一卮轻皓腕，得诗一句胜蛾眉。","山夫野叟只如此，诸君达者应相嗤。","有酒且慢饮，有歌且慢讴。","共君说怀抱，未语先搔头。","良久欲说说不得，胸中有物如山丘。","君不闻东家女子花见羞，十六未嫁便悲忧。","墙头楼上到日晚，马骤车奔如水流。","西家亦有闺中女，月璧龙珠求未许。","有心自比蟠桃花，无言窃笑阳台雨。","谢鲲便是妾家邻，败唇折齿犹相语。","何况五陵轻侠儿，抛金掷玉教人非。","一夫奔处千夫驰，不论荣辱与刺讥。","膻中之蚁醯中鸡，攫金逐兽两眼迷。","主人下马客已齐，拜起俯仰容正卑。","有如六月卖蒲葵，唯恐不售霜风凄。","言至于此良可悲，所以慷慨见于诗。","谁能起舞谁能歌，瓮中有物如秋波。","古来多少无奈何，要须一醉都销磨。","茫茫人间歧路多，不如海水通天河。"]},{"t":"俊老行送林次中赴都司","f":"七言古诗","c":["熙宁察院一开口，谁人胆落御史手。","其时面坚黑髭须，力欲回天气冲斗。","一从蹭蹬作外官，所居不苟心迹安。","刚不可回坚不变，头如霜雪心如丹。","所以论者悦而服，所养有义其质端。","东西南北二十载，一朝有敕却召还。","皂囊封上晓班肃，绣衣步入秋霜寒。","义有所徇乞得身，白日降下天上人。","黄金龙节青囊印，赤帷熊乘朱斑轮。","以其馀才修职分，以其馀力娱精神。","望淮楼上对秋色，玉女花前泣晚春。","时时共帐过南郭，来就陶潜漉酒巾。","与人论事不必合，直无所苟气色真。","持此以往无不可，古人所以为正臣。","淮南一路事如草，嘉苗恶莠俱分了。","中心皎皎如斯乎，外计区区何足道。","两宫日月方齐明，群公戮力营太平。","公议急须招俊老，清风先已过南京。"]},{"t":"鲁恭王祠","f":"五言古诗","c":["帝子非无贤，孰有恭王者。","脱身辞汉储，一芥视天下。","勇故不失义，智故不失几。","身既脱诸险，德亦潜其辉。","群奸非无目，浑浑无罅窥。","阴谋不得奋，佞舌不得施。","以此终其身，万世不可非。","初王受汉封，奉诏实都鲁。","如何千载后，庙貌在东楚。","岂非王之赐，生尝及兹土。","所以淮上人，世世作神宇。","然而鬼神道，不可接形声。","所感唯以德，所通唯以诚。","去年冬不雪，江淮非一城。","人心谁无戚，蔡守最不宁。","守乃款王祠，俯伏祈于廷。","其日腊且尽，其夕大雪零。","前驱方入郭，后乘犹在坰。","田者欢于野，途者欢于行。","如饥哺斯食，如疾医斯平。","骄阳遁无迹，和气来有形。","因知王之心，虽殁不变更。","好诚而乐义，凛凛如平生。","一祷辄已应，为赐良不轻。","侯拜神之贶，民歌侯之明。"]},{"t":"莫饮吴江水寄陈瑩中","f":"楚辞体","c":["莫饮吴江水，胸中恐有波涛起。","莫食湘江鱼，令人冤愤成悲呼。","湘江之竹可为箭，吴江之水好淬剑。","箭射谗夫心，剑斫谗夫面。","谗夫心虽破，胸中胆犹大。","谗夫面虽破，口中舌犹在。","生能人为患，死能为鬼害。","患兮害兮将奈何，两卮薄酒一长歌。","洒向风烟付水波，遣吊胥山共汨罗。"]},{"t":"琼花歌","f":"词","c":["春皇自厌花多红，欲得花颜如玉容。","春皇青女深相得，先教敛与秋霜色。","乃有雪月供光，星榆献白，艑量银汉琉璃湿。","人閒美玉捣作灰，荆山昆山鬼神泣。","天上有人名玉女，投壶之外能为素。","姑射神人解种花，先须此物为根芽。","天罅地窍掬精粹，蟾身骊颔偷光华。","其时正是天地交，二气上下阴阳调。","此花孕育得其正，其閒邪气无纤毫。","所以其色为正色，出乎其类拔乎萃。","一如君子有诸内，粹然其色见于外。","三月将尽四月前，百花开尽春萧然。","扬州日暖花开未，春香不动花房闭。","仙掌秋高玉露浓，蛟人泣下珠玑碎。","黄鹂本是花中客，啼尽好声求不得。","春皇费尽养花心，春风使尽开花力。","春归莺去花始开，谁人放出深闺来。","唐家天子太平时，太真浴罢华清池。","红裳绣袂厌君眼，更作地仙披羽衣。","麻姑睡起蓬莱岛，风吹玉面秋天晓。","洛川女子能长生，水中肌骨成瑶琼。","褒姒不见诸侯兵，尽日不笑如无情。","宋玉移家安在哉，东邻不画胭脂腮。","卓文君去成都速，锦衣金翠慵装束。","吹箫客貌果何如，见说其人名弄玉。","若比此花俱不足，淫妖怪艳文之类。","一如妇人有贤德，不为邪色辞正色。","孀居之女能自持，终身唯著大练衣。","又如正色立朝者，不以柔媚为奸欺。","以此论之乃可重，人之不正将胡为。","论德乃是花之杰，论色乃是花之绝。","洛阳花名古云好，看花须向扬州道。","君不见去年花下吹黑风，霹雳闪电搜玉龙。","此时半夜花光中，不觉屈曲蟠长虹。","又不闻天上琳琅树，种在烟霞最深处。","白云枝叶白玉英，此花莫是琳琅精。","此花爱圆不爱缺，一树花开似明月。","襄王半夜指为云，谢女黄昏吟作雪。","杏花俗艳梨花粗，柳花细碎梅花疏。","桃花不正其容冶，牡丹不谨其体舒。","如此之类无足奇，此花之外更有谁。","世非红紫不入眼，此花何用求人知。","诗人自与花相期，长告年年乞一枝。"]},{"t":"姚黄","f":"词","c":["黄河南畔伊川北，姚家宅是真花窟。","古来多少豪奢儿，埋却千莺万莺骨。","中央精粹得之多，西方秀气来相和。","天与明光常借日，水宫暗脉正通河。","春风如酒半酣时，谁教谷雨报花期。","司马坂前娇半启，洛阳城内人俱知。","姚家门巷车马填，墙头墙下人差肩。","花上红绡都蔽日，花傍翠幕恰如烟。","玉面儿来争供帐，锦袍郎去斗抛钱。","无人不说姚花好，费却春功亦不少。","日长风暖绿梢低，坐上金仙困将倒。","曲尘饼剂和香檀，何以贮之承露槃。","烂锦脱来嫌太艳，鲜衣染就欲骖鸾。","君看此花肌肉丰，一尺馀高千万重。","妆面深藏青步障，宝冠斜堕碧霞丛。","步摇好称钗凤凰，玉镮犀佩珠鸣珰。","帝女何缘心好道，阿娇安用金为房。","绀窠累栖舒雁雏，沈烟喷出狻猊炉。","一种养成馀意态，千花瘦尽春肌肤。","峨峨一器攲且倾，覆杯难辨钟与觥。","染以鲛绡求正色，叩之玉挺希宫声。","魏家红共牛家碧，迭霸花中耸高格。","如今俛首甘下风，九十种中为第一。","此花莫似武昭仪，出得宫来不画眉。","情貌欲为狐媚态，衣裳却是比丘尼。","杨妃本是倾国身，脱却红襦号太真。","河水欲濡头上髻，马嵬犹著旧时裙。","物色一定犹可疑，人心多变宜难知。","容易莫评真与欺，貌或如是心或非。","君不见老庄有深意，万物之中最防伪。"]},{"t":"大松","f":"七言古诗","c":["东海有物天下雄，万灵戮力生奇松。","天精地粹萃其下，沧溟百道来相通。","一根直去穿九泉，一根斜插鲸鱼渊。","远者压折巨鳌背，近者倒缠山根偏。","小枝可就千钧弓，大枝可挂万斛钟。","唯有老干苦难状，吕光营外堆玄龙。","身披北帝雄犀甲，虎贲连臂围不匝。","无计都将大地遮，有心尽把浮云刷。","樛枝入地旋复上，怪怪奇奇非一状。","谷陵相变任古今，土木两行专王相。","列帜空遗渭川垒，犒师留得杨隋帐。","玄驹来撼亭亭盖，渌鱼飞入苍苍浪。","最是半霄风雨声，山妖走尽川魅惊。","十万争挥铁槊骑，百千齐阚黑旗兵。","有时海面波涛小，一部仙韶下蓬岛。","残声逐水散鸣琴，遗响穿云聚啼鸟。","混沌死来凡几朝，清气浊气痕未消。","独叶耸来新盖凤，双柯合处旧藏蛟。","其本既异其事殊，德若有容材有馀。","大鹏斥鴳皆可居，相忘有似江湖鱼。","美哉此木真不凡，能以智免斧斤閒。","过尽工师无所用，庄周应作不材看。","大松大松如此奇，方舆圆盖不可知。","阴阳山海气合离，不然神物相护持。"]},{"t":"芰荷歌","f":"七言古诗","c":["孔雀团花翡翠钿，青皇抛尽买花钱。","渌鱼飞胆大如拳，琉璃瓦坠紫微天。","湘妃曲谱谁可传，彩毫不动斜卷笺。","我家食客常三千，杯槃一样青瑶圆。","麻姑下来寻水仙，不见波澜只见烟。","昨夜秋风吹洞房，起来先著碧霞裳。","半含笑面齐斗妆，家家院落绀为墙。","不道采花人在傍，贪看飞来白纻郎。","亦有美人贞且良，独在碧绡帏下藏。"]},{"t":"双树海棠 其一","f":"五言古诗","c":["独树已难有，双株岂易培。","东风三月后，浓艳一时开。","种是鸳鸯骨，根非玳瑁胎。","英英万千数，滴滴四三枚。","恐淡添猩血，矜香弃麝煤。","鲛绡翡翠眼，宝钿珊瑚杯。","绛节朝真去，丹砂驻貌回。","童妆两株色，花格一仙才。","自得骖鸾侣，何烦跨凤台。","明珠留汉水，碧洞寄天台。","对举霓裳步，高铺绣被堆。","超如御烟雾，势欲摆尘埃。","冶艳皆泥滓，卑枝亦草莱。","好临湘水照，莫近宋家栽。","汉殿昭阳宠，唐家学士才。","浴终兰液溅，帖就茜罗裁。","惜粉轻匀面，偷霞试点腮。","急窥鸾鉴了，齐报玉人来。","不是沾红雪，仍非污落梅。","啼痕才彷佛，伫立各徘徊。","真态有如此，深情安在哉。","歌阑都不语，舞困可堪推。","淡若疑相犯，烘然笑自媒。","画眉郎忽误，挟弹客应猜。","洒绛谁先戏，挥朱亦共陪。","差肩奉青帝，联袂踏苍苔。","好被金钱掷，宜兼玉箸催。","罗巾如可试，瑶枕谩为灰。","供帐朝还暮，买春琼与瑰。","一枝怀旧物，百醮费新醅。","目断秦山远，心分荆渚隈。","柔姿谁是偶，温德汝为魁。","绰绰闺房秀，匆匆风雨摧。","离歌连理曲，送酒合欢杯。","坠脸殷金谷，冤情怨马嵬。","烟波水东去，歧路日西颓。","遗恨传芳草，馀阴伴绿槐。","香魂如未散，相吊复相哀。"]},{"t":"双树海棠 其二","f":"七言古诗","c":["此花出在海州东，千涛万浪围山峰。","不知谁是栽花翁，花根屈曲蟠双虹。","英英斗繁葩葩丰，晨霞夕霞滴不供。","欻有神物射蛟龙，团团血溅摇春风。","超然花格非凡容，吴姬半亸钗头红。","谁人移下海中山，神仙姊妹来人閒。","人閒无玉可消斑，歌姬舞态都且闲。","当时血泪乱瑶关，金槃洗面痕犹殷。","吹箫郎去先骑鸾，妆未成时情已阑。","汉皋台下娇蹒跚，曾解明珠瑶佩环。","无媒不嫁矜殊颜，自共美人香往还。","霓衣同步绀云车，麻姑面上藏丹砂。","绿鬓已坠金钗斜，酒红不著罗衫遮。","且教半笑含春华，但恐分飞成乱霞。","宜哉天下为名花，连根都种名卿家。","温温容态孰可加，有如女德贞无邪。","共君醉倒插乌纱，从他群儿笑哑哑。"]},{"t":"玉女花 其一","f":"七言律诗","c":["扬花可与名玉妃，楚花可与名玉女。","天上瑶台是本居，人在月宫合同处。","一点难容赤水霞，平生冷笑巫山雨。","此女持身色太严，玉璧如槃求不许。"]},{"t":"玉女花 其二","f":"七言古诗","c":["国艳虽殊情太少，蛾眉不画双瞳瞭。","新就明河洗面来，更佩明珠踏瑶草。","不用朱鸾与紫霞，玉麒麟驾白云车。","君看面上都无邪，更看身上都无瑕。","越王国女金可邀，卓王孙女琴可招。","更有秦王家弄玉，嫁人只被爱吹箫。"]},{"t":"和李道源清风谣","f":"七言古诗","c":["漫翁说尽清风好，犹能顾我邀吟藁。","吟时欲倚白云飞，到时恐在红尘表。","有如列子御风行，百骸齐奋双瞳瞭。","借问清风何处来，玉水之心玉山杪。","曾经昆阆拂瑶花，亦度潇湘过蓬岛。","借问清风何处居，深寄碧芦藏绿筱。","芭蕉径舞凤衣寒，薜荔墙翻龙甲老。","遗英堕箨无处寻，一径十年未曾扫。","但恐春深花木稀，定知秋后冰霜早。","快心何羡楚王台，披襟适得麻姑爪。","中山酒客饮辄醒，八斗司徒醉不倒。","箫声易咽笛声哀，客思难平物容愀。","君看檐前避暑巢，不是岩乌即沙鸟。","万谷藏冰山气来，千涛喷雪江声绕。","借问此閒清奈何，况是中宵月华皎。","鸡鸣漏尽眠不成，披衣起看冰壶晓。","便乘枯木饮明河，仍御双凫入冥杳。","藤床角簟无所施，綀布蒲葵价弥小。","有客俄如梦觉时，窃笑梦中何扰扰。","中心无累清则明，蔽者常稀欲者少。","儿啼女笑坐可忘，兽斗禽嬉悟俱了。","毁誉一过遗如空，富贵浮云视弥藐。","古人凛凛良可思，世俗纷纷何足道。","尝闻外物可娱中，所以诗人取萱草。","谁何乘兴为此行，坐摆尘埃出污潦。","贾生可与忘悲忧，楚屈犹将醒怀抱。","区区何用作离骚，弄琴听我清风操。"]},{"t":"望淮篇示门人","f":"七言古诗","c":["闲花落尽春无有，脚踏青红望淮走。","到淮适值晚潮来，满淮鼓吹风波吼。","传声急唤钓鱼船，船未到时洗双手。","买得船中双白鱼，便访村前五青柳。","旋烹野茗问村醪，五柳阴中坐良久。","此行大略类陶潜，但乏黄花白衣酒。","操舟人去一点鸥，帆入云开何处收。","孤鸥浴处依浅滩，修竿放饵投深流。","岂无野妇荷而汲，亦有老翁行且讴。","君看此景直几钱，此时正是夕阳天。","便教金印大如斗，何似鱼庵共钓船。","有人问君莫要说，怀中取出吟翁篇。"]},{"t":"太华","f":"五言古诗","c":["怪怪不可状，谁云仞五千。","直侵黄道穿，高傍白榆篇。","秀气环秦甸，浓岚滴渭川。","掌高长托日，汉狭半含巅。","夜响金丹杵，秋香玉井莲。","排虚摧劲翮，横锐决浮烟。","隐豹文章异，孤松节操坚。","渴虹粗饮涧，饥虎瘦吞泉。","磴道奇花合，杉株古蔓缠。","群材皆挺特，馀壤可陶甄。","义兽期臻萃，妖狐困坠颠。","二关资控扼，万里却腥膻。","真势南冲斗，雄姿北阚燕。","波涛清大海，风雨到穷边。","镇压地常静，磨砻天更圆。","他山皆俯视，何物可齐肩。"]},{"t":"管春风","f":"七言古诗","c":["我是蓬莱山上客，为管春风归不得。","今年更是春来迟，江南未寄梅花枝。","探春童子青霞衣，时时去上青云梯。","春风消息苦不远，瑶台瑶水冰霜浅。","蟠桃花在海东边，此花不烦春一点。","东风日夜来人间，到时先催草根软。","大都红紫心先动，小桃先觉枝头重。","更有纤纤杨柳枝，路傍先得行人弄。","诗翁自爱蟠桃花，鸾鹤不在无云车。","城南夜半无酒家，和冰和雪吞月华。","有客笑中携剑去，偷得银瓶与肥羜。","诗公两眼看浮云，为管春风不回顾。"]},{"t":"高楼春","f":"七言古诗","c":["山阳有客似相如，身著儒衣当酒垆。","尘埃市井不到处，烟霞往往生衣裾。","一竿横挂数幅帛，题云酒味如醍醐。","三月高楼满春色，椒浆琼液盈金壶。","盘罗江笋烹淮鱼，樱实赤玉梅绀肤。","弹丝敲金半空里，醉挥玉爵撞珊瑚。","凭阑直下是烟火，坐上清风凌太虚。","夜深正然红蜡烛，罗幕遮风留客宿。","是人俱爱何家楼，自是何君德如玉。"]},{"t":"淮之水示门人马存","f":"楚辞体","c":["君不见淮之水，春风吹，春雨洗。","青薰衣，绿染指。","渔不来，鸥不起。","潋潋滟滟天尽头，只见孤帆不见舟。","斜阳欲落未落处，尽是人间今古愁。","今古愁兮将奈何，莫使骚人闻棹歌。","我曹自是浩歌客，笑声酒面春风和。"]},{"t":"项羽别虞姬","f":"楚辞体","c":["垓下将军夜枕戈，半夜忽然闻楚歌。","词酸调苦不可听，拔山力尽无如何。","将军夜起帐中舞，八百儿郎泪如雨。","此时上马复何言，虞兮虞兮奈何汝。"]},{"t":"虞姬别项羽","f":"楚辞体","c":["妾向道，向道将军施恩义，将军一心靳财利。","妾向道，向道将军莫要为人患，坑却降兵二十万。","怀王子婴皆被诛，天地神人咸愤怨。","妾向道，向道将军莫如任贤能，却信奸言疑范增。","当时若用范增者，将军早已安天下。","天下成败在一人，将军左右多奸臣。","受却汉王金四万，卖却君身与妾身。","妾向道，向道将军不肯听，将军虽把汉王轻。","汉王聪明有大度，天下英雄能驾御。","将军唯恃力拔山，到此悲歌犹不悟。","将军不悟兮空悲歌，将军虽悟兮其奈何。","贱妾须臾为君死，将军努力渡江波。"]},{"t":"白云先生","f":"词","c":["白云先生面如铁，一片良心似明月。","腹中和气如春阳，齿下清风欲为雪。","群儿走马正欢欢，先生高躅方寻山。","嵩山泰山俱有约，先访王乔后陈抟。","浮丘严驾欲迎子，玉女整衣开瑶关。","山中自是逍遥家，手磨红蕊生龙霞。","鼎中气焰成何物，不炼黄金炼丹砂。","明月一声何处啸，但觉半夜鸾凤叫。","猿不敢号虎不鸣，一夜清风生万窍。","此路高深易迷错，只见先生一双脚。","山中不似俗人家，有客但寻猿与鹤。","西峰犹有秦宫女，身上乱毛如鸟羽。","秦时人事不忍闻，若见斯人莫与语。","先生何以遗时人，先生有语醇乎醇。","莫分巧拙与强弱，莫将外物成天真。","岂不见北邙山下狐狸窟，掘出枯骸与陈骨。","其閒岂无乡原人，其閒岂无强梁物。","强梁物，乡原人，当时尔等空纷纷。","后来之事竟何如，不及痴儿醉梦之浮云。"]},{"t":"山中乐","f":"词","c":["洞里桃花开早春，洞中酒熟宴真人。","红蕊紫芝俱在手，本家猿鹤亦随身。","采拾饤饾随所有，物无不义即是真。","何须谢傅山东妓，却用陶潜漉酒巾。","漉酒复漉酒，何必金印大如斗。","一瓢复一瓢，莫辨人间淳与浇。","时情大抵恶贫贱，此閒却是青云霄。","君不见古人自谓为贤豪，或入于佞或以骄。","但言富贵我所欲，一身不保领与腰。","孔光屈身事董贤，谷永阴与王凤交。","贾谧之党遍天下，望尘拜者尤为妖。","须臾苟得快所欲，终以血肉污斧刀。","假令当日幸而免，后世讥笑安能逃。","岂如孙登但长啸，眼看时事如鸿毛。","嵇康阮籍不与语，何况纷纷儿女曹。"]},{"t":"江南春","f":"七言古诗","c":["今年是处春风早，江南地煖春更好。","春风先把江山扫，次入梅花后芳草。","芳草春深更有情，直共江山到洞庭。","落花流水从武陵，湖中有山春更青。","日欲落时一点明，少年莫上岳阳城。"]},{"t":"欢乐辞","f":"楚辞体","c":["吁嗟人兮，人生凡几何。","汝胡不思兮，故为扰扰而纷纷。","人生如一梦兮，万事如浮云。","汝胡不思兮，胡不为直道兮。","胡为薄物细故兮，疲精而劳神。","汝之所得兮，余以为失兮。","汝之所失兮，余以为得兮。","汝胡不思兮，胡不为义而为仁。","仁义之道如大路兮，人皆可以行兮，汝反以为艰兮。","汝胡不思兮，胡为失性而离真。","祸既自召兮，福亦自弃兮。","汝胡不思兮，胡为乎灾及其身。","善恶之报各以其类至兮，汝胡不思兮，胡不观乎古之人与今之人。","嗟予言不可忽兮，汝胡不思兮。","汝其书诸绅，吁嗟人兮。"]},{"t":"登高辞","f":"楚辞体","c":["九月九日兮，登高何为。","古有此语兮，吾未暇论其是非。","菊花黄兮茱萸紫，二花此时还斗开。","花满握兮酒满杯，人人欲上高楼台。","我与世人虽异好，此时亦难平襟怀。","因思雕虫篆刻事，此文乃是儒之灾。","如今此灾亦可避，不辞万里登崔嵬。","其如此物避不得，但恐积蠹伤良才。","是以天下美璞少，甚于矛戟戕琼瑰。","纵有美璞直万镒，埋之尘土何由来。","圣朝有意去灾害，愿将此物为渠魁。"]},{"t":"淮阴义妇 其一","f":"七言律诗","c":["酷贼奸雠既已除，衔冤抱耻正号呼。","当时但痛君非命，今日方知妾累夫。","舍义取生真鄙事，杀身沈子乃良图。","几年污辱无由雪，长使清淮涤此躯。"]},{"t":"淮阴义妇 其二","f":"七言绝句","c":["淮阴妇人何决烈，貌好如花心似铁。","杀身沈子须臾閒，身虽已死名不灭。"]},{"t":"北神烈妇","f":"五言律诗","c":["海水犹可泛，君身不可犯。","淮水犹可潴，君名不可污。","鸾凤犹可驯，冰霜犹可亲。","不是云閒月，即是月边云。"]},{"t":"赠子瞻 其一","f":"词","c":["翰林主人其姓苏，左臂不任十上书。","几年乞得江与湖，吴中父老争欢呼。","玉堂金户不肯居，肯来南郭寻樵夫。","樵夫所识山与水，除此如何论奇伟。","八月十五钱塘江，海门山下潮头起”。"]},{"t":"赠子瞻 其二","f":"七言古诗","c":["翰林岂特文章工，赤心白日相贯通。","先与吴人除二凶，次与吴田谋常丰。","乃与徒役开西湖，狭者使广塞者除。","溉田不知几万夫，其田立变为膏腴。","世世可知无旱枯，吴人衣食常有馀。","有馀之人善可趣，官司亦可省刑诛。","无穷之利谁与俱，前有白傅后有苏。","翰林如此能成务，吴人叩额呼为父。","未知何处立生祠，定是吴山行坐处。","翰林却过淮之东，无人不看眉阳公。","玉堂气貌将以恭，又到南城寻老农。","仍使尊中酒不空，玉泉最好白醅醲。","便将玉水倾喉咙，须臾醉倒无忧翁。","老翁虽醉不敢迂，记得杭州三事书。","欲毗舜智皋陶谟，事防沮隔有所拘。","翰林此说若行诸，圣朝惠泽可大敷。","譬如雷雨动天衢，旷然霈然而廓如。","无分草木与虫鱼，一时奋振皆沾濡。","满堂饮酒尽欢娱，更无一人泣向隅。","老农虽然无所逋，愿同众口齐欢呼。"]},{"t":"赠子瞻 其三","f":"五言古诗","c":["昔者益州牧，意欲见杜微。","不能以身往，使人舆致之。","虽用为谏议，待士礼已非。","而况君房辈，端坐呼子陵。","子陵胸中气，直与青云平。","岂肯为人屈，彼亦徒骄矜。","孰如扬州牧，自处逊与恭。","德不矜其盛，事不矜其功。","南郭已三顾，迂身为衰翁。","以手书所问，视面叹厥容。","移时能立语，避乘乃鞠躬。","不知古之人，几人能如公。"]},{"t":"感秋和张文潜 其一","f":"五言古诗","c":["汎汎河中舟，莫系河上柳。","君看道傍叶，行人一挥手。","枝条旦旦空，颜色何可久。","坐恐霜霰繁，诸媚归一朽。","我有千丈松，亭亭不可揉。","生在孤峰上，独与云霞偶。","群形靡且纷，不与较妍丑。","群动日夜驰，而以静为守。","守松者为谁，白发无憾叟。","蓬蒿可蔽身，糟糠可糊口。","言者寓于诗，默者寓于酒。","谁知杯酌閒，便是无何有。","念子于我深，我于子亦厚。","记我守松篇，行行重回首。"]},{"t":"感秋和张文潜 其二","f":"五言古诗","c":["张子非不厚，涕泗中夜起。","兰蕙虽已衰，松筠正堪佩。","君爱兰与蕙，忘我筠与松。","君爱洛阳官，弃我淮上翁。","翁如扬大夫，其心甘贱贫。","不投天禄阁，却反离骚文。","骚人虽已殁，万古为忠魂。","欲知冤愤气，但看苍梧云。","冤情寄湘水，冤声寄湘竹。","年年霜露时，夜夜秋声哭。"]},{"t":"感秋和张文潜 其三","f":"五言古诗","c":["秋风一何惨，物形随以变。","秋风如无情，虫鸟声俱怨。","我无外物累，但有屋中燕。","翩翩势将去，盼盼如有恋。","此物虽至微，其旧殆可念。","而况西郭交，年将屈五指。","南城文字閒，东皋松竹里。","气类亦相合，老少两忘齿。","昔居吾舍傍，今在河之涘。","船头缆将解，船上桅将起。","留君恨不早，此役定难止。","如何舍我去，处我复何以。","君看淮泗閒，一派良可喜。","从来病浊污，而今稍清泚。","人方涉其流，冠缨殆可洗。","此行君乐否，一千五百里。","未见洛阳山，先见洛阳水。"]},{"t":"谢周裕之 其一","f":"五言古诗","c":["乐不须丝竹，花不须桃李。","舞不须轻躯，歌不须皓齿。","人生各有乐，顾我如何尔。","我是两柳翁，家在南郭里。","诗酒以为乐，宾客至即喜。","酒味酸或淡，瓷椀粗而伟。","或无一饤菜，但费几张纸。","人情慕富贵，公何视贱鄙。","寒冷载肴酒，暮夜烦屐履。","孚诚非猝然，饤饾亦劳止。","不用卞郎瓠，但坐杜侯椅。","两桌合八尺，一炉暖双趾。","不以药随时，而用缯掩耳。","或啖鱼菹尽，或爱藏蔬美。","或取鱐与腊，或约酒以指。","人皆悦真厚，谁敢停箸匕。","一客癯而清，偶坐为六子。","吟声尚鼓吹，欢情胜罗绮。","俗物无所用，高会有如此。"]},{"t":"谢周裕之 其二","f":"五言古诗","c":["义无所不感，诚无所不动。","诚义既如此，外物斯何用。","以外表诸中，以物将其义。","所谓君子诚，诚亦不虚致。","人有忘恩者，嗟叹而泣涕。","我心非土木，亦有眼中泪。"]},{"t":"赠玉师失鹦鹉词","f":"七言古诗","c":["红蹊翠坞风花客，家有千山万山碧。","一从流落在人閒，玉环绦重金笼窄。","金笼一片烟霞晓，花艳成团柳枝袅。","足穿蜀锦茜靴牢，身著吴绫绀袍小。","参差微露红霞裙，丹喙即是胭脂唇。","真是人閒富贵物，何异朱门罗绮身。","慧性驯姿良可取，只被多言仍巧语。","前身不是亡国臣，即是倾城倾国女。","门外人来连报客，点茶沽酒俱催索。","叫人名字学人言，吴语秦声俱记得。","大都有似原人为，视人欢戚为笑啼。","俗客面前多俚语，逢僧辄诵陀罗尼。","嗟嗟何用畜此禽，岁月养成奸巧深。","莫信口中一片舌，对面千里万里心。","主人曰予未有知，为爱能言不放归。","不道奸心多诈伪，吭肠才饱脱身飞。"]},{"t":"送蒋宪颖叔","f":"词","c":["五岭之南，其极西徼。","其旁大海，木深山峭。","内有溪洞，外有交趾。","皮厚肉坚，铁为骨髓。","雉兔伏藏，猱猿突起。","动如飘风，猛如湍水。","独恩不畏，独威不怀。","扰之则去，抚之则来。","恩之与威，不可去一。","宽猛交济，不可无术。","坐当一面，则有帅臣。","按刑将漕，要皆得人。","以德以才，公称其选。","能不择官，义不辞远。","始闻有命，严装以需。","青毡角簟，药鼎茶炉。","琴堂旧谱，铃阁新书。","史帙签重，诗囊卷粗。","前施斋舫，后设行厨。","公既拜命，不敢宁居。","乃戒徒御，乃建帆樯。","鸣刁击鼓，旗帜开张。","州人感恩，父老童稚。","知不可留，以足顿地。","或前塞路，或后从行。","或献花酒，或犒从兵。","或望于野，或送一程。","即日渡江，江南春早。","雪尽冰消，江山如扫。","柳径桃蹊，梅花芳草。","沽酒村遥，卖鱼船小。","晨散乌群，暮归白鸟。","春正好时，已到岳阳。","岳阳楼下，苍苍茫茫。","岳阳楼上，飞沫浮光。","江山旧物，吴楚凄凉。","夜宿巴陵，晓过洞庭。","湖中水绿，湖口山青。","黄陵古祠，长沙古路。","潇江湘江，风烟古渡。","岳麓茶林，沙洲橘树。","此时春深，衡阳雁去。","时饮一杯，时吟几句。","更望九嶷，清诗无数。","揽辔登山，日日西南。","褰帷叱驭，车不停骖。","乃有部吏，乃有蛮酋。","青衫负弩，锦帕缠头。","公曰使者，实典兵刑。","增置强弩，多募土兵。","宜浚其隍，宜坚其城。","公曰弓手，宜如旧制。","加之训练，可使精锐。","可代城郭，为民捍蔽。","公曰民命，悬在狱官。","不可不慎，不可不宽。","宽于善良，勿失有罪。","恶人如虎，养之成害。","公曰生民，不可无教。","教民之官，县令最要。","今则不然，困于簿领。","甚者可除，烦者可省。","仍复乡官，则无所病。","凡我部吏，各恭厥职。","夜则精思，昼则宣力。","一节当官，赤心为国。","如此教告，如此施设。","吏则心服，民则心悦。","诸公闻之，荐者交章。","朝廷器之，下诏褒扬。","召而用之，优于冯唐。"]},{"t":"谢吕帅寄书","f":"五言律诗","c":["畴昔逢公时，老人悦公义。","率然应公问，而云在藏器。","公以问为好，其法为可传。","老语不记时，人事成恍然。"]},{"t":"送程运判","f":"七言古诗","c":["江南风物可醒酒，江山气势侵牛斗。","大庾梅花入界香，南康瀑布从天吼。","此閒好共吴人乐，井蛟为害须除却。","观风未到庾公楼，褰帷先上滕王阁。","仙籁鸣时独凤吟，剑池黑处双龙跃。","县令宁无种秫翁，还似王弘就翁酌。","最是高贤徐稚坟，急赍酒脯祠溟漠。","部吏争迎使者车，野人夹道亦欢呼。","且得官司减鞭笞，若逢水旱放田租。","关市如何从薄赋，设法通商为远图。","方今圣世虽无事，须修武备戒不虞。","生民所恃在城邑，更严壁垒完其郛。","何况荆湖与二广，溪洞尽是蛮所居。","一日除书遣受降，便持斧钺建油幢。","阵上风神应更伟，军中才气亦无双。","势似疾雷从便道，挥兵直指富良江。"]},{"t":"代玉师谢苏子瞻","f":"五言古诗","c":["海上山翁归，童子言有客。","身披一鹤氅，足曳双凫舄。","控却大鹏头，踏著巨鳌脊。","面带玉山气，手画龙泥壁。","诸仙争进砚，一笑已投笔。","其夕刮两眼，烧却犀一尺。"]},{"t":"寄李道源","f":"七言律诗","c":["春风本是诗家友，典却琴书也沽酒。","呼童去问紫霄翁，近来枕上吟诗否。","不醉不吟将奈何，过却今年春已多。","胸中壮气吐不出，看看空作送春歌。"]},{"t":"酬李道源弹琴之句 其一","f":"七言律诗","c":["数尺焦桐常在手，知子爱歌兼爱酒。","今朝已是二月三，梅花驿使曾来否。","古今多少无奈何，古人慷慨良已多。","为报陶潜且饮酒，无弦琴上不须歌。"]},{"t":"酬李道源弹琴之句 其二","f":"七言律诗","c":["漫翁来索诗千首，须与古人沽美酒。","近来声调太寻常，不知得似阳春否。","漫翁教我歌云何，水远山长春思多。","安得桓伊吹短笛，共君慷慨一时歌。"]},{"t":"和马秀才","f":"楚辞体","c":["君看淮上翁虽老，胸中意气从来好。","白日吟到夜，夜后吟到晓。","门前是双柳，树上无栖鸟。","西边是人家，人家儿夜啼。","四更五更后，往往催鸣鸡。","东边是空庭，空庭清风多。","吟声上河汉，河汉生银波。","移声入明月，桂树无停柯。","蟾蜍不得睡，狡兔将奈何。","清风却下来，直入淮之水。","不知淮东西，波浪如何止。","清风清风不复住，复住射阳湖上路。","宁知烈士怨曹袁，义鬼哀哀冤来诉。","此声未可□臧洪，不须更往吴江去。","吴江心中有冤血，冤声吼兮冤气结。","奈何乎湘江亦有独醒夫，醒时何故沈其躯。","当时鱼腹今在无，此声莫过洞庭湖。"]},{"t":"谢皇华使者","f":"七言古诗","c":["皇华使者将就车，先声即日传江湖。","良民置酒相歌呼，奸人落胆猾吏逋。","手中平握三尺书，权衡轻重量锱铢。","冤声弊狱一切除，宁其家室完其肤。","本朝宽大恩涵濡，一物不被成焦枯。","烦公大手持刀鈇，开塞去拥锄荆芜。","其和易致仁易孚，此行遂与春风俱。","蛮酋鼠窜稽天诛，官兵指日缚狂奴。","皮囊插羽徵军须，人方汲汲公有馀。","藉公之智须公谋，使星已动宜疾驱。","非惟一道无无辜，朝廷南顾无忧虞。","吾州父老将何如，呼其子弟牵仆夫。","絷之维之马与驹，晨炊夕爨空其郛。","亦有下客身鳏孤，怀公礼义心区区。","寄诗如问公起居，公能报我荆州书。"]},{"t":"谢田守","f":"五言古诗","c":["前日李山阳，说公安且裕。","精神健复初，决遣敏如故。","吏复畏其明，民复爱其恕。","可保长康宁，但更勉将护。","寻闻车马出，州人喜可知。","或出车前望，或走车后随。","南郭有贱叟，虽愚亦更喜。","不敢问公者，恐烦答数纸。","贱叟固自讼，太守谦愈劳。","即以出之日，折简亲挥毫。","送之上尊酒，副以黄巨苞。","情意专如此，礼义积已高。","贱叟不能报，自恨如时辈。","所以作诗者，欲公重自爱。","自爱以为国，为国斯为民。","慰我之乡党，悦公之慈亲。"]},{"t":"谢毕令","f":"七言古诗","c":["一身多难过春风，两眼未见花枝红。","近来废却无限吟，今年自觉诗无功。","毕令与我好相识，遗我春醅表胸臆。","知我爱酒兼爱诗，使我吟哦醉春色。","春色半酣正二月，草头争露花争裂。","是花是草属诗家，若无此酒几虚设。","此酒有似君德醇，先入六腑搜吟魂。","相将醉魄御烟云，游遍江淮无限春。"]},{"t":"谢王观文","f":"七言律诗","c":["东野鳏夫未识公，寄声直入茅庐中。","茅庐四面生春风，草头添绿花添红。","东野鳏夫最好吟，感公高义藏于心。","为公制作平戎曲，弹向蔡家焦尾琴。"]},{"t":"谢呼延禁侍","f":"五言律诗","c":["有客从京南，来寻淮上叟。","气貌良肃雍，辞令亦温厚。","如此已可喜，遗我故人书。","须臾四千里，恍惚游江湖。"]},{"t":"昨日之夕和蒋颖叔","f":"七言律诗","c":["昨日之夕谁扣扉，大使遣人来索诗。","吟声一发巢乌飞，一夜清风摇木枝。","吟亦不住风不停，安知半夜风出城。","大使船上风霜清，更添南郭吟哦声。"]},{"t":"寄崔尉","f":"七言律诗","c":["人閒多少无奈何，劝君收泪且酣歌。","不须载酒但相过，共君摧手踏青莎。","东皋閒日苦无多，南城应是合吟哦。","胸中有泪难消磨，惟予诗兴如风波。"]},{"t":"送张君河朔之行","f":"七言古诗","c":["尝闻此道春来迟，山中积雪埋狐狸。","黄河三月冰正合，朔风凛凛吹人衣。","吁嗟客路正寒苦，数千里外将何为。","答云此去非徒尔，有如羽翼投高枝。","主人之贤闻天下，出门舍此将安之。","嗟予赠此复何说，少年养取胸中奇。","古人之学不可废，丈夫之操不可移。","江淮之上亲且老，临行须约将归时。","边城吹角客心乱，此时应望东南飞。"]},{"t":"答范君锡汎汎爱花之句","f":"七言古诗","c":["汎汎爱花非爱一，范掾爱花如此密。","一从春色到人閒，每月弄花三十日。","第一花中爱牡丹，待与金钗共玉冠。","第二桃花及杏花，此花大抵颜色奢。","又爱墙头看海棠，乱点燕脂如急妆。","更无閒暇及芳草，却解回头觑绿杨。","其馀好花有何限，范掾看花眼头烂。","见花如见故人来，寻花太紧攀花慢。","洛阳城内骑马走，山阳城外坐监酒。","坐地爱花情更深，时时取酒为花斟。","谁知有此风流掾，诗情酒兴纷如霰。","好来闲伴老翁吟，老翁是物吟将遍。","海閒亦有蟠桃花，可能同发乘桴愿。"]},{"t":"赠倪敦复","f":"七言律诗","c":["北轩主人吴中清，所居才义皆有名。","曾在东皋压众宾，人皆阁笔诗已成。","其时于我最有情，如今相见情更深。","野人情义亦不轻，夜来枕上为公吟。"]},{"t":"赠张敏叔","f":"七言古诗","c":["张家船上雪压篷，船头船尾堆玉虹。","此时半夜明月中，有人两脚登云空。","其人便是吟哦客，能作清诗无俗格。","更向孤舟雪里吟，一生多难头先白。","白毛吟处彻骨清，喉咙往往生寒冰。","可能乘兴到南郭，戴家为子烧破琴。"]},{"t":"送汝弼赴潭倅 其一","f":"楚辞体","c":["莫说江南行路长，山苍苍兮水茫茫。","莫问长沙城远近，洞庭湖口是潇湘。","去时先上岳阳城，夜宿巴陵探阴晴。","泛洞庭时四五更，出湖口处曈昽明。","平生闻说潭与衡，今来吏隐驻箳篂。","四时所见皆所经，湖青草兮庙黄陵。","眼看君山别洞庭，笑谈却作江南行。","巴陵渡口转船头，一帆风过岳阳楼。","行尽江山到真州，画船旗鼓入扬州。"]},{"t":"送汝弼赴潭倅 其二","f":"五言律诗","c":["不作长沙行，湖湘少斯客。","洁身不可污，好义是所积。","口不出巧言，面不为邪色。","谁可谋定交，斯人不可失。"]},{"t":"富贵篇答李令","f":"词","c":["我有一筒诗，写出千年意。","将令后世观，不是前言戏。","感君再唱洞庭谣，我亦重歌酬子惠。","古人达者尝有云，富不如贫贱胜贵。","君不见古之富贵郎，父祖俱封异姓王。","一门五侯三将军，弟兄同入中书堂。","对开大第连几坊，私门列戟森锋铓。","十二帘捲珠荧煌，双姬扶起坐牙床。","绿鬟红袖花成行，左盼右顾生春阳。","高车食客剑佩锵，堂上已满坐两廊。","巨镬大鼎烹牛羊，玉壶挹酒金船长。","美人拜客求尽觞，歌姬一误已绝吭。","缠头彩币堆如冈，酬歌买笑金鸳鸯。","奴袍火浣直两箱，三千厩马红锦障。","厕帏文绣炉薰香，更衣侍妾如闺房。","主人意气秋鹰扬，其心端如彩凤凰。","一言合意青云翔，须臾睚眦磨刀鎗。","门前腊月可烘裳，一日失势成冰隍。","小者腰领尸道旁，大者连颈宗族亡。","犬鸡散尽空遗墙，野鸟入室山魈藏。","呜呼哀哉可叹伤，至死不悟犹陆梁。","古来如此有多少，岂似洞庭湖上老。","无租无税一生閒，有饭有鱼一杯饱。","日落波閒烟正昏，云开湖口山光晓。","棹翁适自巴陵回，挂帆直指潇湘道。","有言不问俗穷通，何忧可入翁怀抱。","修竿短棹已自足，更有前村一茅屋。","卖鱼沽酒任醉醒，绣户朱门自歌哭。","嗟予未往心先慕，更谢棹翁询去住。","风前月下有谁知，醉魄吟魂自来去。","堂前画作荆南图，梦中记得巴陵路。"]},{"t":"寄管久中","f":"七言绝句","c":["我头未白心先老，吐出精诚为君祷。","若无归计似陶潜，学取萧生抱关好。"]},{"t":"赠查宣教","f":"七言绝句","c":["晚来閒共秋风约，惟有黄花莫吹却。","有人怀抱似陶潜，待向东篱共花酌。"]},{"t":"答卢鲁山秀才","f":"五言古诗","c":["吾道一于中，所得无背向。","吾神充乎形，所得无衰王。","气入春风和，兴与秋鹰扬。","有累已驱除，无酒亦酣畅。","外如不可挠，内如不可状。","更读鲁山诗，何乐可能尚。"]},{"t":"签刘子静秀才并示鲁山","f":"五言律诗","c":["难逢一笑乐，易遇千黄金。","而况吾胸中，所得盖已深。","百物正烂熳，二子方歌吟。","一乐已自足，两乐交吾心。"]},{"t":"和鲁山感春 其一","f":"七言古诗","c":["君看纷纷能几时，一番情态随春尽。","欢者常少戚者多，共君且趁春风歌。","莫学时人种花草，不似山中松桂好。"]},{"t":"和鲁山感春 其二","f":"七言古诗","c":["一笑一啼何日休，一荣一悴何时尽。","樽中野酒亦无多，日伴吟翁慷慨歌。","茅屋窗前栖乱草，胜却花閒绣裀好。"]},{"t":"呈次中","f":"五言律诗","c":["烦公素叶诗，答我碧芦柬。","我亦为长句，枕上不合眼。","两城俄相通，一意如同撰。","用韵亦无殊，便可书之板。"]},{"t":"述怀寄吕帅","f":"七言古诗","c":["君看关西山壁立，春云突尽春空窄。","浓岚洒去渭川寒，孤峰深与秦天碧。","白云流水岂无情，立马吟诗定相忆。","且倩东风先寄声，我整西装期已迫。","吟到秋风放我归，归来待作潇湘客。"]},{"t":"和李自明 其一","f":"五言律诗","c":["青松何岩岩，生在孤高处。","能鸣月下风，更入云閒路。","云汉何渺茫，远过衡山阳。","松风上河汉，高韵落三湘。"]},{"t":"和李自明 其二","f":"五言律诗","c":["我有金玉交，家在临流处。","秋来诗更清，吟喉饮风露。","崔子在何方，清思满残阳。","不知今夜梦，几度过衡湘。"]},{"t":"送沅州通判","f":"七言古诗","c":["过湘江时君且听，但恐水中有冤声。","当时无地容屈平，众人皆醉嫌独醒。","烦君须吊独醒翁，以酒注之鱼腹中。","不须以物缠米筒，但投诗去责蛟龙。","为君质直有古风，能高其义哀其忠。","投诗已罢吊已终，寄声急报南城翁。"]},{"t":"赠吕帅","f":"七言古诗","c":["玉门关静边烽息，回首金城赵充国。","绣帽霜须马上吟，诗兴如云满秋色。","最好青门长乐坡，灞桥路上情更多。","绣岭风烟新草木，潼关形势旧山河。","洛阳城阙秋风紧，有诏疾驱催大尹。","两瞳直是有精神，管取无宽亦无猛。"]},{"t":"寄道原 其一","f":"五言律诗","c":["好笑李诗翁，寄身明月中。","饥肠吞白露，醉口吐清风。","时时跨霜鹤，步步凌秋空。","相呼且相待，略住白云峰。"]},{"t":"寄道原 其二","f":"七言绝句","c":["漫翁身上霜可刮，酒未醒时诗已发。","急放人去守船门，恐向河中捉明月。"]},{"t":"和李自明","f":"七言律诗","c":["病叟相逢恨不早，蒹葭敢比瑶林好。","谁作羊车卫玠看，不道好玄扬子老。","使君礼义高如山，清风更可清尘寰。","明日王君来访我，陶潜欲卧君须还。"]},{"t":"送吕掾归扬州","f":"七言律诗","c":["年年二月春色稠，今年二月寒未收。","路上无花空酒瓯，清吟清啸到扬州。","到扬州后登高城，绿波芳草连江津。","吟哦若望江南春，梅花便是江头云。"]},{"t":"寄范掾","f":"七言律诗","c":["昨日沽酒典布袄，今朝所典未可保。","最好绵衾剩典钱，又恐夜寒妻懊恼。","两务酒官俱见怜，沽我好酒如甘泉。","为报孟光莫恶发，待将黄卷换青钱。"]},{"t":"送晦叔","f":"词","c":["两人俱是白发翁，不用语言情意通。","且喜胸中无一事，一生常在平易中。","愿公活百岁，我活九十九。","白发变成黄发翁，回来同把一杯酒。"]},{"t":"赠张敏叔","f":"七言律诗","c":["张子生平最多难，未老头毛白一半。","头虽更白诗更清，正作诗时人莫唤。","头不肯转身不移，口中声调霜风凄。","太清宫殿月明时，第一莫吹松竹诗。"]},{"t":"送辛朝奉","f":"七言律诗","c":["几日迟迟辞我去，梦中犹忆南城路。","不知昨夜月明时，泮水宫中来几度。","三月春风正向西，我将心逐春风飞。","送过高丽亭下路，别遣春风随客衣。"]},{"t":"送崔主簿赴雅安","f":"七言律诗","c":["见说西川好山水，此行便是秋风里。","洛阳年少本多才，马上一挥吟一纸。","凤凰羽翮非徒尔，上击浮云九千里。","枳棘须教别鸟栖，自趁春风便飞起。"]},{"t":"送张九掾兼简同事钱明府可与慎叔良蔡彦规同一笑也","f":"七言律诗","c":["有人独酌南窗酒，春是故人诗是友。","故人消息在江南，为我江头探杨柳。","诗人见春双眼明，迎春送春俱有情。","何况温温张九掾，可无诗句赠君行。"]},{"t":"送王潜圣","f":"七言古诗","c":["公车待报凡几年，萧生罢去心浩然。","盐渎野中寻旧隐，扬子江头呼渡船。","太湖波浪湿秋天，洞庭橘柚生红烟。","马踏新霜吴岭外，猿啼小雪建溪边。","关西夫子虽迟暮，行笑行吟正安步。","菑川海上牧羊儿，亦说公孙放豚去。"]},{"t":"寄张文潜","f":"五言古诗","c":["不知今之人，谁识张县尉。","勿问胸中事，但看面上气。","所谓人英者，正是斯人辈。","前年南郭中，文酒日夜会。","一从舍我去，忽忽再逾岁。","今兹岁且尽，为子吟不睡。","起坐却就枕，伸头出纸被。","约是三四更，老老抱双脚。","此时吟正酣，声调不可却。","春风起淮东，须臾到嵩洛。","往往入子家，但子眠不觉。","子觉将奈何，声尽情思多。","上东门外路，洛水生春波。","还我大松来，不用寄诗歌。"]},{"t":"代简呈通理察院","f":"七言律诗","c":["去年过时花未红，今年过时春未融。","春未融时得子来，吟翁面上生春风。","吟翁近来成白颔，种种头毛无一半。","唯有胸中气未衰，更得公来激吾懦。"]},{"t":"送诗僧严上人","f":"五言古诗","c":["日晚孤云飞，故山在何处。","八月凉秋时，正望江头去。","定无尘埃气，清风与白露。"]},{"t":"送端叔 其一","f":"词","c":["端叔上马去，巷口马头转。","我唤端叔时，端叔急回面。","记取此时意，莫使落风埃。","上东门外水，正望楚州来。","此水一来不复见，不及黄沙塞头雁。"]},{"t":"送端叔 其二","f":"词","c":["是物可寄情，是物可寄声。","不须使黄犬，延州歧路远。","莫怪不登淮上楼，只为淮水不西流。","直待衔芦雁却回，其时随到天尽头。"]},{"t":"再送端叔","f":"词","c":["关中日落时，但见山相接。","塞上闭城时，但听吹芦叶。","延州平安火过早，月出山头照孤堡。","王家池上醉欲倒，铜钵声中诗已了。","落笔挥成露布草，主人更索平戎表。","文章意气入杳冥，金船插羽如飞鸟。","诸军鼓吹高牙晓，大纛门开扑馀燎。","壮士犀衣剑气寒，客身依旧红霞绕。","陆生待寄梅花枝，庾郎莫爱芙蓉好。"]},{"t":"呈路倅","f":"五言古诗","c":["三十年居官，而无一椽屋。","随身清风高，所至义行足。","今兹尽室来，何可久船宿。","奴僮已暴露，勿使乏饘粥。","也须谋外物，种取柳与菊。","记取节节高，爱我茅檐竹。","其时花尽落，手把麦黄绿。","公酌我须釂，公吟我须续。","慷慨见怀抱，静介无所欲。","最是谒祠堂，老泪潸可掬。","迩来六七岁，病叟头已秃。","万事置浮云，壮气自满腹。","感激论忠义，犹爱唐衢哭。","更思桓野王，把笛吹一曲。"]},{"t":"奉呈河中教授","f":"五言律诗","c":["不息之谓诚，诚所以入德。","无微而弗大，何往不可适。","惟其能言者，自求其所得。","唯其自得之，久而能弗失。"]},{"t":"奉酬守道","f":"七言绝句","c":["教官昨自江南来，但有清风无尘埃。","曾遇芙蓉池上客，仍过方家旧钓台。"]},{"t":"赠蔡长官子","f":"七言绝句","c":["去年冬至第一日，省墓人回船过急。","不知两眼血乾无，使我时时为君泣。"]},{"t":"谢董元达","f":"五言律诗","c":["鄱阳董元达，七叩樵夫门。","新菹乏三韭，浊酒欠一樽。","名言有馀理，老怀思共论。","今日复一来，刮我两眼昏。"]},{"t":"谢石运干仲谋","f":"词","c":["奉议清而温，义心无所遗。","已能顾白须，更与吟清诗。","更与吟诗清奈何，樵翁一夜为吟哦。","吟到四更月出后，床头看月忽成歌。"]},{"t":"寄陈伯模","f":"五言律诗","c":["腊月初四日，有人叩吾庐。","言从江上来，手把鄱阳书。","发书见康强，细字盈数纸。","仍说九雏中，两雏正飞起。"]},{"t":"送李光道","f":"五言古诗","c":["忆昔见子时，我在西关住。","顾我已衰朽，爱子特明悟。","其后十数年，于此数见之。","气貌日益好，胸中即可知。","貌者德之表，精神气所为。","气无所不适，其本在养颐。","所养得其正，其美充四肢。","子是名公孙，家法能自持。","子学有旧业，尤富礼与诗。","重之以所养，何适而弗宜。","古人有大路，行者皆坦夷。","夫以子之明，岂惑于多歧。","修鞭与长辔，逸驾无停时。","古人亦何人，勿问皆可追。","昨见子笔札，老人为子喜。","其言逊而恭，贲然有文理。","愿子更勉之，莫忘老人语。","所居求正人，正人德之辅。"]},{"t":"卜居一篇二章别望之 其一","f":"五言绝句","c":["卜居何所尚，静轩栽此君。","万事付流水，一心游白云。"]},{"t":"卜居一篇二章别望之 其二","f":"五言绝句","c":["亦有灵寿杖，可登浮光山。","圣朝须旧德，玉笋虚清班。"]},{"t":"西山高寄崔刑部","f":"楚辞体","c":["西山高，胡为高。","上有磨天之巨势，下有黄河不测之险，甚于蜀道之难。","西山高，长安之路如云霄。","乘无逸驾兮飞无劲翮，我欲往兮有千艰百险之相辽。","西山高，长安之路如天遥。","夜短梦不到，白日其心劳。","西山高，我欲往兮方穷处于蓬蒿。","恩之大兮报不可以速，太山之重兮置之有若鸿毛。","西山高，无如之何兮徒引领而长谣。","青门路兮有时到，愿公之寿兮如松乔。"]},{"t":"答崔伯易白雪之句","f":"五言古诗","c":["北叟有奇歌，调与声俱绝。","此歌本难名，强名为白雪。","一唱白云开，再唱青云裂。","朝唱迎朱霞，暮唱入明月。","声在明月宫，桂树生秋风。","秋风吹明河，银浪翻长虹。","河汉与海通，安知声所终。","如此谁可知，但问牵牛公。","如此谁可听，直须登青冥。","酒仙骑赤龙，诗仙骑长鲸。","一夜到平明，北叟声且停。","遗响来南城，犹似孤鸾鸣。","南公对北叟，阮籍逢孙登。","阮籍正长啸，孙登作凤鸣。","羞杀阮步兵，笑杀孙先生。"]},{"t":"送张宜父赴南从幕府","f":"七言古诗","c":["江南秋色芙蓉香，满江秋水倾银潢。","泛水依花人姓张，涛翻浪涌挥文章。","突然出者何苍苍，巨鳌曝背来中央。","鼋鼍仰首伏四旁，登临谈笑得庾郎。","安得霜鹘腰胯长，骑上秋空追鹔鹴。","北望海门形势强，美哉壮观吴封疆。","若将前代论兴亡，直谈孙氏到陈梁。","凡为佐命可哀伤，其诸奸孽如豺狼。","倾谗正直诬忠良，以国贩卖为贾商。","歌姬舞女金满堂，不须为盗持刀鎗。","身虽幸免遗其殃，子孙戮辱甚犬羊。","所以不欲读史书，鼻洟目汁沾髭须。","润州支使相如无，山阳老子如唐衢。"]},{"t":"寄吴行甫","f":"五言律诗","c":["人事无穷时，白日常纷纷。","夜久静不眠，枕上还思君。","形神有合离，忽过江之濆。","已过江之濆，更随东南云。"]},{"t":"赠荆南王秀才天爵集虚二堂求诗仍往武陵","f":"词","c":["天爵名甚高，集虚名甚悟。","悟高已与俗人非，更望武陵花下去。"]},{"t":"送李昂长官","f":"楚辞体","c":["征南兵势欲平蛮，军声杀气秋风寒。","南国此时霜霰早，八月草黄枫叶丹。","江有渚兮山有麓，君向洞庭何处宿。","四垂天幕乱波平，九嶷山送愁岚绿。","日斜叶落黄陵祠，月明风起清湘竹。","愁娥远放峡云来，冤臣莫借江声哭。","雁号孤喙度苍梧，猿叫哀肠抱霜木。","君看樵坞与渔村，绿橘黄柑随柿熟。","此行正合风骚情，县衙仍在衡山足。","新岚老翠滴吟窗，风松云溜生琴曲。","衡人侧耳听先声，报道官来不碌碌。","可使汝农无逃田，可使汝市无冤狱。","汝胥可脱簿书烦，汝民可免鞭笞辱。","日中放吏不坐厅，夜半投金不受嘱。","回时唯载俸馀钱，茶满衡山无一掬。"]},{"t":"谢江倅","f":"五言律诗","c":["病叟在所收，越已为高义。","就而饮食之，盛具烦亲致。","让榻行殊礼，朋酒代贿币。","非徒追古风，兼使奉时祭。"]},{"t":"谢李次翁","f":"五言律诗","c":["次翁情义高，不在古人下。","惠我春山芽，清吟为增价。","记得西窗无，言诗遂及雅。","且待李张来，说子到清夜。"]},{"t":"答李昂长官富贵贫贱终篇之贶","f":"词","c":["前日正凭几，长须叩我门。","手置一筒诗，义高辞且温。","三读至终篇，尤爱子所存。","我有不言意，子已自得之。","余将缺不报，嘉意忽如遗。","吾闻诸物理，动静固其性。","静有不如动，动有不如静。","所病入于邪，大率要归正。","穷通存乎时，死生存乎命。","与其以邪通，孰如以正穷。","汉之主父偃，其卒败以凶。","不义而有生，不如死于夭。","所以君子徒，而恶蹠寿考。","谓富不如贫，谓贵不如贱。","其说岂徒尔，亦各有所见。","贫贱与富贵，亦不必去取。","始也以道得，卒也以道处。","岂特区区身，时乎非小补。","万世赖其法，天下受其祜。","所以古君子，得之亦不拒。","处之不以道，君子所不与。","景公马千驷，孔子贤夷齐。","曾孟藐晋楚，原颜甘冻饥。","我爱张车骑，我爱郭汾阳。","大业中兴汉，馀基再造唐。","天资既忠厚，以义能自将。","德盛不敢肆，功大不敢当。","匿迹远权势，以身系存亡。","以宽不以刻，以逊不以强。","兹可谓之贤，虽盛其何伤。","博陆岂不伟，区区蔽孽显。","当时虽已幸，其后卒不免。","至于充谧辈，何足污齿牙。","机云死好进，乐晏死佞邪。","下近隋唐閒，其辈尤可嗟。","甚者弊天下，非惟凶而家。","所以富与贵，有时而可恶。","淫夫所不从，奔女所不娶。","色美而行非，嫫母胜西施。","所以汉烈女，深恨蔡文姬。","文姬文姬其奈何，如姬之辈可悲歌。","我欲采药山之阿，亦欲把钓披渔蓑。","茫茫人閒歧路多，不如海水通天河。"]},{"t":"赠陈留逸人 其一","f":"五言古诗","c":["不知何许人，忽在陈留市。","生来无得失，物则有泰否。","春时看物生，秋冬看物老。","大意寓之笛，馀情付云鸟。","无处不可居，不问江与湖，亦不问田庐。","今夜入城市，往往呼狂夫。","狂夫胜独醒，以身葬江鱼。"]},{"t":"赠陈留逸人 其二","f":"五言古诗","c":["有人持一管，不用芦叶卷。","能作陇头声，其女操六板。","吹者寓其声，拍者会其情。","情声与气貌，内外俱和平。","时时入酒家，便插几枝花。","归来无一事，醉卧日西斜。","人或问所得，答云无忧嗟。","或问其所欲，何物可相累。","我爱斯人者，富贵所不如。","有如此娱乐，作如何称呼。","呼为无忧人，画作无忧图。","更画几枝花，酒瓢与酒壶。"]},{"t":"谢叶祖洽","f":"五言律诗","c":["叶公有高义，常叩茅茨居。","不嫌杜微病，更附荆州书。","龚遂合驰传，郭伋方驻车。","海人受公赐，约在秋风初。"]},{"t":"送沈判官","f":"七言律诗","c":["四月芙蓉花未开，王家客去登瑶台。","瑶台高在白玉京，麟毫玉谱书姓名。","名儒庾子能清悟，肯学买臣与严助。","受福王明不为身，泽遍生民便归去。"]},{"t":"酬传道","f":"五言律诗","c":["有客从东来，乃是徐方秀。","言行过乎恭，篇章一何富。","顾我白发叟，赠以青瑶枝。","我将投木桃，桃始开花时。"]},{"t":"寄龚豫之","f":"五言律诗","c":["海角龚支使，平生无所苟。","而今五十六，岂肯变所守。","岂独龚支使，古来无奈何。","达人自知命，世俗徒悲歌。"]},{"t":"谢永城令陈德任举","f":"五言律诗","c":["县令有馀义，以碣表孤坟。","昔尝致酒脯，两手披荆榛。","今乃重加惠，使与群冢辨。","数十百年后，名亦附公传。"]},{"t":"寄豫之","f":"七言律诗","c":["掘地须臾便得泉，主人劲直使之然。","此水埋藏千万年，岂无勃勃气冲天。","主人意气蛰亦久，不知谁是掘泉手。","最好盐场作选人，面目心肠无所苟。"]},{"t":"赠郎朝散","f":"七言律诗","c":["仕宦何须论权贵，司宾且喜属郎倅。","篇章淮上至今传，德性清温善酬对。","神仙船过北神来，应思诗老任员外。","沙河路上且吟诗，犹有黄花伴吟醉。"]},{"t":"乞留草赠路倅 其一","f":"七言绝句","c":["膝上已无三尺桐，门前更少两株柳。","唯有庭芜似野风，告留且伴东皋叟。"]},{"t":"乞留草赠路倅 其二","f":"七言绝句","c":["君看我家门外草，欲把烟姿慰吟老。","谁知人静雨馀时，还似村深日斜好。"]},{"t":"答倪令挑战之句","f":"七言律诗","c":["南城病客方闭门，西郭檄书俄入手。","霜涛洗开醉合眼，清风吹起困低首。","诗阵须知少敢当，吟魔已遁无何有。","可笑将军不用机，示以强兵殆非诱。"]},{"t":"答俞簿","f":"五言律诗","c":["诗者为乐章，所以贵声调。","我虽好之笃，子乃得之妙。","子妙既相逢，如何慰病翁。","有时闻数阕，尽日想清风。"]},{"t":"送思权随赵守往扬州","f":"七言律诗","c":["一自移船便恐行，城中两夜梦河汀。","武林夫子在船宿，往往将身梦入城。","夫子恋德虽未休，不过送公到扬州。","我遣吟魂无远近，直过潇湘江渡头。"]},{"t":"谢存中送四花并酒","f":"七言古诗","c":["有人自折四般花，手中四色成云霞。","瑶瓶贮酒白如沙，呼童急送野人家。","一般花是水林檎，白处偷红红不匀。","笑脸易残留恨色，浅妆难就带啼痕。","无夫少妇善居寡，以礼自防容不冶。","君看盈盈闪色桃，酒红睡起未全消。","意待倾城又倾国，花中偷得两般色。","深色桃花将奈何，猩猩血染春衫罗。","欲成鸾凤吹箫急，借涂铅粉施朱多。","却是梨花白为胜，四色花中容最正。","若与梅花相并时，花叶花柯较粗硬。","为花倾出瑶瓶酒，香泉急溜蚍蜉走。","两手各擎花一枝，深闪桃花将与谁。","主人醉起欲骑马，自插乌纱带取归。"]},{"t":"寄蒋大漕","f":"七言古诗","c":["大使莫忧淮上老，无山可望梅花少。","梅花可种山奈何，日中枕上山更多。","不开两眼行一步，悬崖绝磴青嵯峨。","岂无閒僧坐林下，亦有樵子持斧柯。","起来恍惚从万里，便买玄猿栽薜萝。","人閒流水寓之意，天外白云来者歌。"]},{"t":"寄汝弼","f":"五言律诗","c":["行人过江来，遗我数纸书。","书云困行役，家事仍纷如。","真州嫁孤妹，苏州取病弟。","方且谋医药，相期未可冀。"]},{"t":"古风一篇赠梅使君","f":"五言古诗","c":["古有贤令尹，为贫民出租。","今亦有贤令，代民偿所逋。","何必偿所逋，不忍伤肌肤。","君以古人心，能为古人义。","我是吟哦翁，亦有古人意。","几夜月明中，为君吟古风。"]},{"t":"寄江子和","f":"五言律诗","c":["客有江子和，时时慰衰老。","寄我江黄书，其意不草草。","恐我有疾病，欲我得寿考。","古人正如是，但恐今人少。"]},{"t":"送吕明府","f":"词","c":["古人吕明府，而爱南郭吟。","不嫌我衰朽，知子有良心。","良心何爱吟笑翁，为我平生怀抱空。","一心常在浮云外，万事付之流水中。"]},{"t":"送陈明府","f":"五言律诗","c":["人而有常德，古人良所贵。","乃有陈明府，其如斯所谓。","予常察之久，得之辞与气。","何以为不忘，比诸大羹味。"]},{"t":"再送吕明府","f":"词","c":["昨泛江都船，曾作寒冷篇。","今浮清洛水，仍是清风里。","野岸有幽花，孤村有酒家。","此酒与此花，尤宜日西斜。","大抵人生要自乐，保必持花与杯酌。","有无酒花俱笑吟，为我回头望南郭。"]},{"t":"有客所养厚一首赠送吴安中归省其兄","f":"五言古诗","c":["有客所养厚，气貌已可知。","而况五日閒，议论未停时。","亹亹来逼人，我觉老且疲。","何人慰衰朽，须臾合复离。","所为安中喜，鸿鹄翩翩飞。","最好西湖上，一床同寝衣。"]},{"t":"和吴奉议","f":"七言律诗","c":["一物勿令侵吾神，一事勿使摇吾真。","养诸内者气欲息，散所滞者体欲伸。","为报平居既安叟，幸为平世难老臣。","亦有閒僧晤言否，呼来伴子逍遥身。"]},{"t":"赠程秀才","f":"词","c":["我是南郭翁，门前两株柳。","君是谁家隽，肯来顾衰朽。","兄弟六人应姓荀，一人错认李膺门。","不谈俗物唯谈文，更说长淮谣主人。"]},{"t":"所祝送宁秀才","f":"词","c":["所祝君者，岂敢如息。","在养在正，在进在德。","在好闻过，在亲亮直。","精讲明辨，所以臧也。","早夜思索，不可忘也。","以正而通，以正而穷。","以义而始，以义而终。","勉之戒之，其所养者，勿使害之。"]},{"t":"送张子厚滕县行","f":"七言绝句","c":["战国甚于狼虎斗，孟子力将仁义兴。","岂无父老传闻事，为我访之邹薛滕。"]},{"t":"送钱思权","f":"五言古诗","c":["子处我为兄，我以子如弟。","何待去呼唤，自可来相视。","不敢苦留君，留君住数日。","待问六年事，但恐烦纸笔。","昨日从早起，等君到昏黑。"]},{"t":"赠张教授","f":"楚辞体","c":["君看两鸿亡所依，江南塞北何所归。","一鸿留在淮之湄，一鸿独犯霜露飞。","哀复哀兮将奈何，愿期弟子废蓼莪。","先翁经却忧患多，为君半夜成悲歌。"]},{"t":"戏答 其一","f":"词","c":["我喉已吞霜，我口复吞月。","吞霜吞月太粗豪，五脏心胸总清彻。","东家亦有人中清，一从年少名豪英。","文章馀事能用兵，蛇矛丈八折羽旌。","排成大阵将横行，太华屹立洪河倾。","螭腾豹躣哮虎鸣，斗胆可落突眼睛。","冲车突骑出不意，锋不可当声动地。","前军已胜后兵继，唱罢凯歌毡帐睡。","将军但筑受降城，老大不烦修武备。"]},{"t":"戏答 其二","f":"词","c":["君看月上霜，君看霜下月。","不知月盖霜，不知霜盖月。","但觉我一身，上下中央四旁总澄彻。","霜是何物如此清，月是何物如此明。","白头老翁坐中庭，半夜可数毛发茎。","群阴积聚纯粹精，虾蟆吸尽瑶池津。","银河两道来藏冰，玉龙走入蟠千寻。","倩君两耳为我听，其閒恐有波浪声。","初出海时蛟螭鸣，却入海时潮头生。","小鲸走入尾闾内，大鲸大鳅寒不睡。","莫教射倒金银宫，鳌背神人难设备。"]},{"t":"赠徐彦","f":"五言律诗","c":["昔者见君面，记得秋风时。","遗我寿阳书，故人情可知。","一从西城居，复来南郭住。","时时还忆君，不知在何处。"]},{"t":"寄朱少府","f":"七言律诗","c":["过巴陵后北风猛，洞庭水白湘波冷。","江头风猛霜霰多，竹节老硬竹梢紧。","此时谁为湘江行，其人有道直而清。","宜其所至无冤情，蛟龙不复侵屈平。"]},{"t":"代人上陕西漕生辰","f":"五言古诗","c":["尝闻五百岁，一有贤人生。","议者实在公，仍与圣运并。","全资五岳粹，高挹太元清。","与帝为元老，与国为名卿。","中外试已烦，玉振而金声。","漕柄虽云剧，其道安足行。","宜哉廊庙器，蹇蹇王之庭。","春色满长安，春山围长坰。","春芳森绮绣，春风锵瑶琼。","秦封几千里，富庶而安荣。","人与春意和，净竦长安城。","何以献公寿，庄氏之椿龄。","何以献公福，洪范之康宁。","黄河为富贵，太华为功名。","此诗何为者，聊用歌群情。"]},{"t":"赠慎伯筠","f":"五言律诗","c":["掘尽昆崙山，美璞才一双。","何人横大阵，未战敌已降。","秋风吹老桧，明月沈空江。","礼天者大事，其器不可尨。"]},{"t":"送秦漕","f":"词","c":["维古之人，厥修有道。","使臣之美，于诗可考。","其马维良，曰骐曰驹。","六辔贲如，如沃如濡。","而况其身，洁不可污。","身不可污，其可辱乎。","载驱载驰，载驰载驱。","虽则驰驱，咨询咨诹。","以来厥修，聚其所闻。","使于四方，如圭如璋。","烨烨煌煌，为国之光。","其美无疆，后人不忘。","维时不忘，而有斯人。","斯人维何，维古人是思。","古人是思，是思是为，如璋如圭。","如圭如璋，维德之辉。","如酝如藉，维德之仪。","维德在躬，维日不足。","是问是辩，善也弥笃。","美哉是乎，诚自中出。","诚隐而显，成己成物。","维诚则然，亦在所勉。","勉而弗已，终之不倦。","所往所居，老生腐儒。","穷商贱贾，野人山夫。","彼所知者，出于精专。","情伪利害，穷根到源。","其可遗乎，可使之言。"]},{"t":"寄太康知县周宣德","f":"词","c":["冬之季月，月及上弦。","太康书来，慰此皤然。","并其成法，别为一书。","敏而有术，使我嗟吁。","考其大指，官之楷模。","官守其约，事总其要。","何弊不除，何隐弗照。","如陛高台，俯视四旁。","不持度量，是物可量。","挈裘之领，提纲之纲。","维简维能，维能维精。","维精维思，维思维诚。","既诚既明，既信既行。","日有馀力，民亦閒暇。","不肯顽恶，孰为欺诈。","不出一符，不遗一力。","或将尔车，或负尔穑。","四境之内，如云坌集。","一岁之事，先期以办。","私无所扰，公无所患。","至于盗贼，无处伏藏。","情既暴露，脱身奔亡。","吏案可空，刑书可阁。","俾尔室家，既安且乐。","岂唯太康，世蒙其业。","凡百有司，皆来取法。","勿毁其成，在彼后人。","勿有所嫉，勿摇勿倾。","如川斯流，勿窒其行。","美哉太康，不负厥官。","到官之日，坐席未安。","所成者大，所及者远。","何以加之，加于所勉。","又何加焉，不倦于终。","遗之无穷，智者之功。"]},{"t":"送张漕正","f":"词","c":["以正名官，居官以正。","岂惟朝廷，生民之幸。","名官以正，居官以直。","岂惟生民，宗庙社稷。","积者为庆，流者为泽。","远者无疆，久者无极。","此奚有他，一言之力。","维时我后，智勇兼有。","揭日当天，操杓运斗。","随手如意，不劳而治。","明明赫赫，有因有革。","所因者宜，所革者当。","维当维宜，生民之望。","维正维言，民之望之。","维言维正，何以尚之。","越有诤臣，义不顾身。","白刃可蹈，赤心可倾。","既曰真矣，弗变弗移。","既曰直矣，弗阿弗随。","何事可沮，何利可回。","不可则止，其可则为。","往司厥官，往成厥功。","回天论事，有祖之风。"]},{"t":"送赵漕称","f":"词","c":["人之古貌，心未必醇。","心醇貌古，或非通人。","我视赵公，其貌甚古。","心德俱醇，通达明悟。","我曹山野，岂足尽知。","但据所见，以类可推。","大河之说，何其通达。","精简平允，明辨昭皙。","盖其心得，身至自阅。","坐而可言，起而可设。","又云九河，勿守故迹。","但求禹意，然后为得。","此说尤奇，汉儒不及。","我自黑头，尽心河渠。","逢人辄问，三十年馀。","得公此说，庶几成书。","既讲大河，遂及赈饥。","如此方略，所系甚大。","乡官胥徒，实为巨害。","使领虽贤，吏不可乏。","必得官吏，斯为善法。","可为利泽，可制奸猾。","如其备预，莫若义仓。","勿取军民，勿法隋唐。","裒多益寡，斯谋乃臧。","损上益下，民悦无疆。","可自王公，下至选人。","每月之俸，百取一分。","凡千钱者，其出钱十。","斛取一升，缣取一疋。","各从本所，贮其本色。","主者不劳，但视其籍。","不移一符，不烦一力。","月知所增，岁知所积。","出者不劳，如无所出。","其所损者，毫毛涓滴。","一仓之内，诸所畜聚，尽是官俸。","凡皆为民，不得移用。","即移用者，法不可纵。","不以去官，不以赦原。","设法如此，其谁敢干。","古人所贵，讲辨之学。","应而弗精，询谋诹度。","惟是陋生，不足待问。","问而不应，应而不精。","君子不为，非人之情。","惟是弗精，面目腼然。","在乎复教，庶无后愆。"]},{"t":"送赵守","f":"词","c":["齐有高密，有沂有沐。","旁有泰山，莒鲁郊关。","粤有人焉，气清神耸。","立节以高，处义而重。","维节维义，肇自布衣。","根本渊源，所养可知。","以义为文，洪畅精微。","以义持守，隐如坚城。","以义作为，动如精兵。","面有正色，口无谀声。","赤心可割，肝胆可倾。","以义接物，不矜不骄。","以义临民，实庇汝曹。","实康实济，实恺实悌。","民实宜之，实受其惠。","方今天下，虽曰治安。","正在所恤，民有饥寒。","公所往居，岂肯草草。","戒吏侵渔，欲民温饱。","言者为准，行者为表。","维恕维平，除烦去扰。","狼摧其牙，虎缩其爪。","父子室家，足以相保。","作此诗者，岂徒然乎。","庶使其民，传告欢呼。"]},{"t":"谢玉师","f":"五言古诗","c":["河沙亦可数，海水亦有畔。","师恩及吾母，其多卒无算。","远者穷无边，深者入黄泉。","黄泉儿莫到，慈母忽有告。","冥冥长夜中，如行白日道。","儿一别母容，可想不可逢。","凭师无量恩，恍惚如相通。","师恩若何为，真诚与高义。","幽明虽有殊，母子各有慰。","欲报将奈何，肉镌骨可磨。","泣尽感恩泪，慷慨成悲歌。"]},{"t":"送云鹤山人","f":"词","c":["星非甘公，卦非焦赣。","善言五部，枝干迭用。","所据甚精，所发必中。","辅之以教，其益弥众。","以刚止邪，以柔止讼。","躁者使静，义者使动。","仁使之修，虐戒之纵。","险者使平，浮者使重。","如此庶乎，殆可折衷。","行矣勉之，斯言可诵。"]},{"t":"送李守孝博","f":"词","c":["外官之重，其惟使乎。","使者之重，兵政刑诛。","持挈纲领，设施楷模。","以实去伪，以清革污。","善本须养，恶根必锄。","非严不肃，非宽不舒。","非威不行，非信不孚。","诸如此类，一不可无。","而况百粤，岭阳海隅。","其俗彍悍，戒吏侵渔。","缓之则怀，扰之则吁。","又况其徼，溪洞蛮居。","虑要先定，戒须早图。","使臣之重，不其然欤。","命使维何，曰山阳守。","维山阳守，其质忠厚。","既明而恕，惟所自有。","以严以威，以左以右。","维恕维平，维详维精。","所济维敏，所孚维诚。","刑无必用，事皆原情。","或虚其狱，或空其庭。","称者盈巷，传者盈城。","四境之内，尽为欢声。","其体则庄，面无浮气。","其目则瞭，心无所蔽。","不激不诡，不迁不泥。","亦不自务，亦不自恃。","好谋好询，使臣所贵。","维询维谋，何以酬之。","维时武备，为国修之。","我闻番禺，熙宁之前。","弓手之外，枪手三千。","总计一路，何啻万数。","因而循之，不烦招募。","可增其籍，可当土兵。","不费斗粟，不用尺缯。","其便如此，何惮弗兴。","付之善吏，以成其能。","训之练之，按阅有程。","可如汉制，选择骁锐。","号为奔命，无所不备。","岂惟广东，自广而西。","闻命即赴，势张力齐。","如声如响，如鸷如飞。","如决大水，从山赴溪。","盖神速者，用兵之奇。","仍坚其城，仍浚其池。","虽有交趾，正如狐狸。","伏藏窟穴，其何能为。"]},{"t":"赠武夷旅人","f":"词","c":["武夷旅人，而有气节。","不肯琐琐，亦不屑屑。","持此守身，归慰其亲。","既慰其亲，亦告乡人。"]},{"t":"赠庞公","f":"词","c":["司马德操，来就庞公。","杖履直入，名姓不通。","坐其堂上，指挥呼索。","催令作黍，云我有客。","庞公妻子，堂下罗列。","拜且听命，奔走陈设。","此时庞公，适自外归。","忽见司马，其喜可知。","一堂之上，相从笑语。","其旁观者，莫分客主。","我读其书，爱其古风。","真厚如此，精诚交通。","量如溟海，义薄云空。","至于妻子，亦为叹者。","苟非其人，往往见骂。","盖有是夫，而有是妇。","能佐夫义，善敬夫友。","可警薄俗，可示厥后。"]},{"t":"送裴守","f":"词","c":["维时西南，巴蜀一道。","强楚侵疆，故蜀东徼。","水激以猛，山迫而峭。","人性坚悍，地形险要。","孰往而使，孰抚而教。","惟帝难之，乃眷东顾。","曰山阳守，智足知务。","能正而和，能察而恕。","严所以立，宽所以辅。","性不狎侮，躬有法度。","是表是仪，可俾可付。","其往钦哉，所居必裕。","公拜稽首，驰传以起。","入境褰帷，登山叱驭。","设施有本，先后有序。","可者立行，不可立去。","公曰来汝，吏受约束。","天子圣人，汝勿苛酷。","民心无他，罪生不足。","穷阎荒村，颓垣破屋。","岂可罗网，更入牢狱。","公曰兵官，当去其懦。","贼侮则犯，贼畏则挫。","勉之在勤，戒之在惰。","兵要素练，慎勿安坐。","公曰县尉，县无城郭。","奸者鼠伺，狂者兽攫。","一邑性命，弓手是持。","选择补之，训练使之。","即有能者，有以劳之。","即不能者，戒之告之。","在昔汉氏，蛮多变者。","失信失恩，扰之故也。","今则不然，有以处汝。","德以服汝，威以御汝。","恩以结汝，信以固汝。","汝无自恃，皇帝神武。","凡公敕戒，吏皆奉行。","何法不恕，何刑不平。","何兵不练，何技不精。","一纲尽举，百为大成。","盗贼衰息，蛮夷信服。","四封之内，截然整肃。","小人有依，良民受福。","天子嘉之，驰传以召。","慈母喜之，载色载笑。","神亦祚之，永锡难老。"]},{"t":"送范宣德","f":"词","c":["客有斯人，而有美质。","可养而充，其在不息。","养之以正，充之以义。","何适不可，何为弗至。"]},{"t":"送李推官","f":"词","c":["物有所兴，因人而就。","其人维何，所性忠厚。","能谋而果，能明而究。","身任其责，力成厥构。","既成之法，可继于后。","入门而东，自南而北。","如污斯隆，如枉斯直。","如塞斯通，如隘斯辟。","如翼斯张，如衡斯举。","如蔀斯赫，如阒斯睹。","室有明窗，墙有坚堵。","地无游蚁，穴无伏鼠。","既完既成，既安既处。","师乎师乎，岂可苟然。","心为道本，身为义先。","心之所无，道不可传。","身之所无，口不可宣。","唯正唯直，求己以全。","以义以命，如耕平田。","处心积虑，贯通神明。","无忝乡校，勿负朝廷。","成人子弟，慰人父兄。","二三职事，其亦警戒。","欲善诸外，先治诸内。","存诚防邪，集义养气。","作伪心劳，作德心逸。","如此两句，守而勿失。","谨佐尔师，各修其职。","庶乎诸生，其则不远。","已修加修，已善加善。","不率者从，不类者变。","子弟如此，父兄所愿。","可慰乡人，可成学风。","可酬其劳，可称厥功。"]},{"t":"送乔司法","f":"词","c":["乔掾循循，有如寒士。","面无浮气，能训诸理。","可养可充，曰正曰直。","其维思诚，其在不息。"]},{"t":"送贾镇卿","f":"词","c":["萧县大夫，气质端劲。","其中所养，不邪而正。","正以辅才，恕以辅明。","面无谀色，口无谀声。","若斯人者，宜于王庭。","而况一县，为惠为泽。","恕所以惠，威所以立。","猛宽得中，韦抗是也。","诛奸殄寇，有贺齐者。","东汉庞参，作守汉阳。","政所以茂，实繄任棠。","以君之正，以君常德。","力追古人，是宜是适。"]},{"t":"可养一章赠别范子舟","f":"词","c":["可养可充，曰性曰气。","以君美质，斯已可贵。","养而充之，何所弗至。"]},{"t":"送山阳宰","f":"词","c":["大夫三年，平恕如一。","静而不烦，民安厥室。","大夫去矣，何以述之。","我述民言，民实德之。"]},{"t":"赠吕公侍讲","f":"词","c":["我敬吕公，以其德齿。","敬之爱之，何时已已。","美哉吕公，文在其中。","见乎外者，古人之风。","维贤有德，神相其祉。","何以祝公，勿药有喜。"]},{"t":"送汪宫教","f":"词","c":["尧亲其亲，教官得人。","所性忠厚，貌纯气真。","学为耕稼，经为本根。","实之为行，贲之为文。","辞令出口，法度在身。","大学小学，其谁弗循。","循之维何，维义是适。","不骄不肆，无邪无僻。","大者敬义，如汉元王。","小者乐善，如汉王苍。","乐善敬义，何有不臧。","保躬无悔，受福无疆。","无疆之福，维顺维忠。","维忠维顺，维师之功。"]},{"t":"代诸生送蒋守 其一","f":"词","c":["明明楚侯，为国之光。","王明是选，王命是将。","皇皇者华，六辔如濡。","辔且如濡，其德可孚。","其孚维何，洁不可污。","皇皇者华，六辔沃若。","辔且沃若，其德可度。","其度维何，清不可浊。","洁也不污，清也不浊。","德则不渝，泽则不涸。","民则宜之，民则乐之，神亦作之。"]},{"t":"代诸生送蒋守 其二","f":"词","c":["长淮之南，楚为最剧。","守者为谁，以才以德。","守既视事，未逾厥月。","吏则胥畏，民则胥悦。","物来必应，事至立决。","守之动静，皆有法度。","不苟不简，不暴不怒。","处烦以敏，辅严以恕。","庭无滞讼，狱无冤囚。","民无愁叹，俗有歌讴。","古之三府，谣言奏事。","今岂不然，兼采公议。","付之使节，是以用之。","付之远俗，是以重之。","其俗既平，其刑既清。","章德表功，来朝两宫。","两宫圣明，柱上记名。"]},{"t":"送山阳太守李公","f":"词","c":["维淮东南，孰为州最。","曰李大夫，实劳于外。","公虽老矣，方壮方刚。","处剧而静，不烦以详。","大率郡县，事如草芒。","而况楚州，车轮中央。","侯繇其冲，客出四旁。","北迎大车，南乱巨航。","公移私讯，骈檄交章。","大夫酬应，谈笑以将。","大夫甚健，日力有馀。","事至立决，罪无囚拘。","教以好语，完其体肤。","据案而坐，处之须臾。","吏休两廊，庭中空虚。","所以楚人，爱公之敏。","挥刀截绳，弯弓射隼。","敏所以辅，其本则明。","穷奸破伪，窥心见情。","譬如工师，譬如良匠。","手无所设，目无所妄。","物随以就，法随以施。","大寻小尺，方矩圆规。","嗟民虽愚，所以有几。","曰敏曰明，曰公有体。","曰不生事，曰不悖理。","不阿不随，不激不诡。","民以是悦，众以是和。","何以送之，其可弗歌。","在昔奏事，实采谣言。","凡我乡党，宜歌斯篇。"]},{"t":"送江倅","f":"词","c":["昔之别驾，则有王祥。","其民歌之，海隅称焉。","今亦有人，能绍厥后。","民之悦之，称不容口。","庶民所见，乃其皮肤。","见察情伪，见敏簿书。","见法平恕，见狱空虚。","事见无留，才见有馀。","己不敢肆，人安厥居。","其所见者，止于君子。","良士大夫，谓其所性。","得之刚毅，所以能断。","所以无蔽，所以敢为，所以勇义。","决遣簿书，是其馀事。","汉之朱博，赵张龚尹。","抚恤大众，何独古人。","王祥虽贤，失在宝刀。","正而平者，心则不摇。","人或赠之，则弗受之。","借曰受之，何佩有之。","弗佩曰正，曰平维平，宜于朝廷。","用之一方，一方之纲。","在我者正，是谓为政。"]},{"t":"送蔡守","f":"词","c":["维淮之南，楚为剧州。","守土之吏，孰明以周。","蔡公既来，爰究爰乂。","明维照奸，威维沮伪。","维明维威，无敢恣睢。","侯曰可矣，其治孔易。","乃兴学校，示之本原。","儒居儒处，礼容义言。","乃修释奠，教民之恭。","有严其色，有孚其颙。","乃行乡饮，躬为主人。","拜辱拜豆，盥洗献宾。","其仪孔肃，其礼孔均。","乃召父老，父老俱来。","幅巾短褐，浩其盛哉。","父老升矣，侯则兴矣。","父老坐矣，侯则妥矣。","父老未醉，笑歌其声。","父老既醉，发白颜赪。","父老去矣，侯则举矣。","馈之物矣，告之语矣。","其语维何，维善是示。","善者使修，恶者使止。","告尔宗族，告尔邻里。","维时父老，奉之以行。","维时庶民，亦克用承。","悖傲者沮，善良者兴。","狠不敢斗，强不敢凌。","不义之讼，莫涉吾庭。","行之期年，几移其风。","吏事用简，狱牢数空。","道上之物，必归其主。","行路之人，无或敢取。","逋攘慝奸，明其购赏。","倾其巢穴，破其支党。","侯曰未也，江淮之患，不备不虞。","乃召尉逻，乃呼卒徒。","乃张尔弓，乃操尔殳。","乃坐乃作，乃驰乃驱。","勇者乃奋，怯者乃舒。","我备既强，我戎既整。","小剽之攘，破胆缩颈。","侯之方略，可以捍边。","捍边如何，威名毅然。","何兵不精，何城不坚。","虏不敢犯，敌不敢前。","侯有所祈，曾不旋日。","雪霶雨零，舆濡衣湿。","维其有德，将之以诚。","神由以格，物由以亨。","侯之为人，不患不恕。","维恕维威，维民维宜。","侯为使者，不患不威。","维威维恕，维感维豫。","侯之察狱，不患不明。","维恕维明，维平维精。","维时岭表，维时海隅。","闻侯之风，既安且需。","冤者使伸，戚者使愉。","吏长则进，物残则除。","抉其已垢，刮其已污。","维有其才，无施不可。","用之本朝，维良维佐。","用之一方，一方之纲。","嗟今之人，莫如侯者。","侯之所为，可示天下。","维其可示，是以可歌。"]},{"t":"谢李自明","f":"词","c":["养以其久，真以其积。","维积维久，是以为德。","德而德之，或表而失。","德而弗德，然后能造。","孰为斯施，孰为斯报。","德其德者，伐干以斧。","弗德其德，培以根土。","德乎斯乎，其孰禦乎。"]},{"t":"赠胡大夫","f":"词","c":["兵有三难，一曰难知。","二曰难处，三曰难言。","眇忽精微。","伟哉胡公，讲辨必精。","以兵为难，是为知兵。","是为力学，是为老成。","惜乎老矣，未见设施。","其谁知公，胸中之奇。","弗施于兵，施于有政。","所在所居，斯民之幸。"]},{"t":"送吕清叔 其一","f":"七言绝句","c":["寒水如烟霜似雪，半夜疏窗透明月。","此时有客正不眠，淮上吟声无断绝。"]},{"t":"送吕清叔 其二","f":"词","c":["昨夜月初圆，今宵月初缺。","月圆月缺本无情，惟有文通恨难说。"]},{"t":"送吕清叔 其三","f":"七言绝句","c":["惨惨黄昏天欲雪，萧萧淮浦人声绝。","风击寒云雁正鸣，客眠孤棹灯方灭。"]},{"t":"赠王观文","f":"七言古诗","c":["一自西征登将坛，探其窟穴除其残。","邻羌馀喘虽偷安，匈奴右臂殊不完。","闻公姓字摧胆肝，穹庐部落匿可汗。","何当饮马朔海乾，雄文高勒燕然山。","古来从事多壮夫，凯歌得意更豪粗。","共公谈笑观投壶，醉笔挥成露布书。","归来却佐神圣王，爱贤乐道不敢忘。","德功甚盛谦尊光，始终一节郭汾阳。"]},{"t":"答张文刚","f":"五言律诗","c":["张子问著书，使我长嗟吁。","有意在黄绢，无能任白驹。","筋力如老骥，颐颔生霜须。","二子少且壮，努力相雕枯。"]},{"t":"答刘子静","f":"五言律诗","c":["风兰不复采，风树何由静。","一日复一日，大龙自驰骋。","无限好花开，何异秋风景。","洒泪报君诗，正是鹤孤警。"]},{"t":"答颖叔","f":"七言绝句","c":["大使莫忧淮上叟，万事付之诗与酒。","若问我家何所营，为比陶潜少三柳。"]},{"t":"和张文潜晚春 其一","f":"五言绝句","c":["春在亦饮酒，春去亦饮酒。","若问此閒时，便是无何有。"]},{"t":"和张文潜晚春 其二","f":"五言绝句","c":["昨日枝头红，鲜鲜染人指。","今朝寻不见，已在污泥底。"]},{"t":"和张文潜晚春 其三","f":"五言绝句","c":["麦颖未黄乾，桑实半红湿。","恰得一犁雨，田事正火急。"]},{"t":"和张文潜晚春 其四","f":"五言绝句","c":["人事无如何，多于道傍草。","但问酒有无，莫管老不老。"]},{"t":"和张文潜晚春 其五","f":"五言绝句","c":["人生少娱乐，閒日亦有数。","药草正肥时，好望云山去。"]},{"t":"和张文潜晚春 其六","f":"五言绝句","c":["风暖燕窠牢，云晴鸟翅健。","物生自有乐，亦各适其愿。"]},{"t":"示诸生","f":"七言绝句","c":["子莫为文学纤丽，须是浑浑有古气。","本源要在养诸中，不然恐汝为时辈。"]},{"t":"谢张尉","f":"七言绝句","c":["鱼菹乃以玉版名，可将苦酒试光明。","张华陆机勿下箸，盘中恐作霹雳声。"]},{"t":"送秦漕","f":"七言绝句","c":["以身送客情几何，以心送客情最多。","任意所之无远近，不论山险与风波。"]},{"t":"赠郑毅夫","f":"七言绝句","c":["摩天羽翮森森齐，胸中壮气蟠虹霓。","区区世俗谁相知，青云歧路看如泥。"]},{"t":"送陈长官赴衡阳","f":"词","c":["楚天摇落霜风早，山色依依江渺渺。","洞庭水寒帆影孤，雁声正在衡阳道。","君不见屈原憔悴贾生夭，遗恨至今犹未了。","日晚江头船住时，行人莫望江边草。"]},{"t":"南山有奇木赠慎彦邻","f":"五言古诗","c":["人皆患穷饿，子独无寒饥。","子乃何为者，汲汲售于是。","汉之公孙弘，唐之张柬之。","子岂不知此，与世相驱驰。","南山有奇木，荦荦松桧姿。","此木在深山，年代不可知。","烟云终日荫，雨露早夜滋。","一干可为栋，一枝可为榱。","耽耽廊庙中，小大皆可施。","子岂不知此，汲汲将何为。","子其自努力，发愤而忘疲。","孔孟非异域，行者皆可几。","退之虽绝足，大步亦可追。","嗟子之兄弟，与我如四支。","余言子其听，无使我歔欷。"]},{"t":"答何楚才","f":"五言古诗","c":["有客能操耒，而舍其良田。","有客善攻玉，而探珠于渊。","二者之是非，子以谓何如。","子乃舍所急，若是其渠渠。","然余有二说，可为不可为。","所为不可者，子家无寒饥。","所谓可为者，奉养之所资。","余此二说者，子当慎择之。","余尝奇子貌，亦尝怜子文。","不能为子谋，嗟哉空云云。"]},{"t":"还崔秀才唱和诗","f":"词","c":["元白有馀势，孟韩无困辞。","子美骨格老，太白文采奇。","当时大道久破碎，人人文字萎薾而支离。","天生数子将卓卓，鸱鸮正成群，一鹗摩天飞。","嗟君不与数子共，使君逸气填塞无所施。","我来虽无知，黄金白玉看如泥。","自从诗卷一入手，掣然直上青云梯。","十宵不睡亦不困，厌宾日日关柴扉。","秋风猎猎吹横河，苍天万里生银波。","起来半夜吸一口，睡魂酒病都消磨。"]},{"t":"赠慎叔良 其一","f":"五言律诗","c":["昔日黑头交，今为白发叟。","约是三十年，情好于此久。","且待花开时，同把一盏酒。","君看我门前，兼有两株柳。"]},{"t":"赠慎叔良 其二","f":"五言古诗","c":["昨日故人来，慰此白颔叟。","两叟忽相见，面色如饮酒。","将此酒色面，抵却春风寒。","饮酒岂易比，欢好良所难。","我已五十八，君已五十七。","人生勿草草，两公须努力。"]},{"t":"赠慎叔良 其三","f":"七言律诗","c":["相逢便吐胸中奇，直道而交与世违。","砚席已逾三载共，鸾凰须约一时飞。","嗟予从事于今僻，似子知音自古稀。","好去上书言得失，买臣犹取虎符归。"]},{"t":"赠卢鲁山 其一","f":"五言绝句","c":["充囊勿用钱，古律长短篇。","子勉如不已，斯文终可传。"]},{"t":"赠卢鲁山 其二","f":"五言古诗","c":["一诗将两年，不出非空然。","为子有佳行，重为进德篇。","孔孟有常处，四通八达路。","其道甚坦夷，行之莫能御。","夜思而昼行，求至慎勿遽。","存诚防他歧，积微从寸步。","积之能不已，其率可驰骛。","仁义固其常，忠信乃先具。","正直常与游，前却慎勿顾。","所谓气马者，尤宜审其御。","孟子言最详，扬雄亦深悟。","勉之复勉之，子无忽吾语。","凡我今之人，皆欲达其所。","而况乡闾中，待君为处女。"]},{"t":"寄秦少游","f":"五言律诗","c":["子用心于我，知者蔡彦规。","彦规今死矣，谁能述所为。","若说子用心，古人如此稀。","顾我不能报，临老形于诗。"]},{"t":"赠钱思权 其一","f":"五言律诗","c":["好笑两学官，果然作不了。","子去恐无船，我眠幸有草。","君看野田中，閒花亦不少。","昨日有人来，赠我吟诗藁。"]},{"t":"赠钱思权 其二","f":"五言律诗","c":["有客叩茅庐，时来见鳏老。","今朝二十七，春风有多少。","共子乐有馀，如何醉不倒。","坐中忽索马，归慰亲怀抱。"]},{"t":"赠钱思权 其三","f":"五言律诗","c":["有客怀刚义，无物能干抱。","堂有白头亲，惟忧甘旨少。","其家十五口，行计亦草草。","也须谋饘粥，不可使饥倒。"]},{"t":"赠钱思权 其四","f":"五言律诗","c":["同室与乡邻，势与他人异。","义当同子去，岂敢徇于利。","但恐登舟时，无以慰亲意。","沽与玉瓮醅，岂烦酒官义。"]},{"t":"赠袁评事","f":"五言古诗","c":["今年七十岁，岁岁增康宁。","人閒有寿鹤，天上有寿星。","更若欲齐椿，但看南华经。"]},{"t":"大河上蒋宝文","f":"五言律诗","c":["大河者大事，我辈安足明。","野人好狂言，夫子知本情。","念此有官守，不可从公行。","心方愧古人，渤海之王生。"]},{"t":"寄王十七丈","f":"五言律诗","c":["舒州怀宁尉，是我丈人行。","两遗小书去，其礼若非抗。","何德称殊礼，胡颜拜首贶。","更致附吟哦，以问公无恙。"]},{"t":"寄张芸叟","f":"五言律诗","c":["豳有张芸叟，言行俱无邪。","摄官为别驾，虢州仍近家。","寄书来报我，便可取其兄。","两缣为一被，同卧复同行。"]},{"t":"寄吴安中","f":"五言律诗","c":["十月十四日，人自江东来。","书询杜微病，粟代陆生梅。","高义有如子，恤病而救灾。","老身将入土，报之何如哉。"]},{"t":"赠魏教谕","f":"七言古诗","c":["酒官幸得风流掾，任贵须沽不须贱。","共君吟笑醉春风，诗似阳春共黄绢。","祝君长作白头吟，台背肌肤冻黧面。"]},{"t":"赠陈诚父","f":"五言律诗","c":["东海陈诚父，回身过山阳。","登时来见我，言恕而行方。","主人太山野，薄意似酒浆。","仍劝客莫饮，恐酒有所伤。"]},{"t":"赠张才父","f":"五言古诗","c":["自笑陶潜辈，相逢却论兵。","谁知阵上客，时访郭西生。","喜公抱忠义，顾我非纵横。","今来求笃论，古事聊一评。","奇正要两存，众寡不可轻。","兵间有万变，所惭思弗精。"]},{"t":"赠陈纠","f":"五言律诗","c":["子来别我时，送子到巷口。","约去百步地，出巷更引首。","乃与二三子，回所舍依依。","故人情可见，何用送行诗。"]},{"t":"和蒋龙图 其一","f":"五言古诗","c":["公之所设施，道德之馀事。","有性给其才，无物蔽其意。","大车积以载，牛刀迎者解。","以要操其纲，以妙观其会。","善誉不尽知，善毁没可讥。","校之古人辈，彼若有所为。","公之所然者，以智不以凿。","其力日以裕，其济日以博。","至于我曹者，使相望相闻。","犹能领官属，携诗叩吾门。","先看陶家柳，次看陶家菊。","茶中许投花，坐上呼燃烛。","顾我为乐叟，勉我以不倦。","我是孟东野，终附郑公传。"]},{"t":"和蒋龙图 其二","f":"七言律诗","c":["鹢口衔波船过猛，樯幔排云北风紧。","耽吟俊老绣衣寒，传诗急使筠筒冷。","诗同使者从何来，谢安枕上吟哦回。","吟哦去望江南雪，雪中往往梅花开。"]},{"t":"和李自明","f":"词","c":["自明多奇辞，更为奇怪歌。","好共卢仝骑绿耳，吟哦直上昆崙坡。","更令张旭辈，醉中挥笔书嵯峨。","安用呼老子，两脚跨橐驼。","有命得坚疾，无术除沉痾。","一从水木迭用事，肺为废物囚网罗。","而况小暑之后有初伏与大暑，更添热厉兼昏魔。","骨閒赫赤炭丸走，皮上烘炙铁手摩。","有时一屋之内但觉汤火近，不辨镬与锅。","手持匕箸腹先胀，酒到喉咙颜已酡。","青黏漆叶无所用，鸟伸熊顾其奈何。","五脏孰云可湔洗，百骸终恐生虫窠。","脱身难上赤霄路，梦魂忽泛沧溟波。","沧溟尽处是星汉，有人常弄机与梭。","枯槎去后更无客，历历赤桂来经过。","取得良书挂牛角，持将斗柄吞明河。","但把明河吞满腹，不去龙田拾瑶玉。","便控鳌头出海来，霞点云痕在眉目。","起穿两柳行青莎，怪歌使我须吟哦。","吟哦作文非小事，要为法度后世无讥诃。","大抵文章本诸内，归之无憾斯平和。","拟之于经辅之友，精讲明辩相切磋。","君虽病肝，其心可用教。","我虽病肺，心亦不自阿。","日夜思索，已矣老矣，所学亡失多。"]},{"t":"和倪敦复 其一","f":"五言古诗","c":["一别北轩君，参商与胡越。","先声从西来，尘榻为君拂。","吟行时引头，吟坐即摇笔。","未见问行人，既见惜短日。","缓颊相问劳，剧谈尽忠切。","耳窍虽塞豆，口角自流沫。","崔子祥而论，祝令闵且说。","篱閒菊参差，樽中酒澄澈。","把酒互相劝，投菊两不绝。","客主莫分辨，僮仆亦娱悦。","若比庞公家，妻子不罗列。","悔令唱骊歌，惜不醉寒月。","念子为令尹，行义高突兀。","当官志不回，敛版腰可折。","与俗皆背驰，而慕古遗烈。","竹节生便坚，剑气久已发。","其时东野外，频烦大夫谒。","篇章日相寻，气势谁可遏。","仍携大轴来，使我两目阅。","人事有合离，岁月成恍惚。","逸翮腾方高，骏马足不蹶。","子实不我忘，我亦不子忽。","与之气类同，见之心欲豁。","金城不可破，铁槊不可夺。","择交盖已定，言志亦已合。","布阵诗甚详，挥洒手不歇。","更约临行时，斯言可赠别。"]},{"t":"和倪敦复 其二","f":"七言古诗","c":["县令醉时花满睫，县令卧时云满榻。","其时北面竹轩凉，雨声霎罢风飒飒。","美人争唱醒酒歌，湿透红绡声未匝。","玉容沃以沉香水，瑶槃冻屑珠玑杂。","魂梦适从何处来，帐中犹把浮云踏。","自说骑鸾向阆风，到时玉洞诸仙合。","只被桃花迷杀人，行顾瑶关忽双阖。","枕上犹能走笔吟，累累吐出珠千蛤。","压倒唐时白与元，两翁相顾如何答。"]},{"t":"答范君锡 其一","f":"七言古诗","c":["醉中吟问风流掾，酒价太高何日贱。","如何使我典衣沽，诗人未有春衫绢。","诗人有酒不须歌，自有春风四面多。","山阳才吏倪大夫，烦君为我特致书。","正月腊寒犹未去，诸君吟坐待围炉。"]},{"t":"答范君锡 其二","f":"词","c":["报漫翁，无钱可沽酒。","青衫典不得，黄卷卖不售。","借问公田中，秫米种几斗。","休管将来旱与水，莫为妻儿种粳米。","兄来留下二万钱，送与酒家主人未。","不然何计见春风，空将花插白头翁。","簿书营营几时了，何如载酒访扬雄。"]},{"t":"答范君锡 其三","f":"七言律诗","c":["漫翁俊逸几无偶，安得吟诗类中酒。","却是蓬头枕上吟，不知还有人嗔否。","漫翁春思今如何，但觉新诗老更多。","却应笑我粗豪甚，颇似将军出塞歌。"]},{"t":"呈周裕之","f":"五言律诗","c":["海陵周裕之，又为淮上客。","来寻南郭路，不见张宜伯。","宜伯在京口，不知谁与游。","时时应北望，只可见瓜州。"]},{"t":"恨君不作洛阳客","f":"七言古诗","c":["余虽不作洛阳客，自有吟魂兼醉魄。","吟魂醉魄御风行，看尽千花万花色。","宁知洛浦有人留，挽定春衫归不得。","脱身误入嵩山中，山中逢见白须翁。","欢然借我双金童，须臾引入花林中。","乱花深处迷西东，花光照天香薰空。","金盆挹酒双瑶钟，酒酣邀我吟春风。","绀云千丈挥玉虹，搜罗万变穷神功。","有人飞下紫霄峰，酬诗解佩声玲珑。","余方却步不与语，笑余不似郑交甫。"]},{"t":"答钱思权","f":"五言律诗","c":["两个学官位，都来一步地。","青眼与白眼，五日不相视。","子为道涂行，我为刀笔吏。","两者较勤劳，大同而小异。"]},{"t":"妾薄命","f":"七言古诗","c":["妾家本住吴山侧，曾与吴姬斗颜色。","燕脂两脸绿双鬟，有貌有才为第一。","十岁能吟谢女诗，十五为文学班姬。","十六七后渐多难，一身困瘁成流离。","尔后孤贫事更多，教妾一身无奈何。","其时痴騃被人误，遂入朱门披绮罗。","朱门美人多嫉妒，教妾一身无所措。","眉不敢画眼不抬，饮气吞声过朝暮。","受尽苦辛人不知，却待归时不得归。","罗衣满身空挹泪，何时却著旧时衣。"]},{"t":"如今","f":"七言律诗","c":["如今八月九月时，吟翁还爱黄菊篱。","及见清风杨柳枝，时时对柳呼酒卮。","头颅半秃牙齿稀，村田未去寻牛衣。","为唱骊驹不及时，主人先道无庸归。"]},{"t":"梦中作","f":"七言古诗","c":["诗翁吟袖忽翩然，使脱红尘腾紫烟。","一身病骨如生翅，两道银河不用船。","奔星相随趁明月，鸣鸾引去追飞仙。","琅玕树下夜宴起，云童为汲瑶山水。","仍遣诗筒寄阆风，诗筒落下烟霞中。","人閒知是吟哦翁，举头齐望青冥空。"]},{"t":"谁何哭","f":"词","c":["谁何哭，哀且危。","白头母，朱颜儿。","儿忽舍母去，母何用生为。","架上有儿书，箧中有儿衣。","儿声不复闻，儿貌不复窥。","谁何哭，哀复哀。","肠未绝，心先摧。","母恃儿为命，儿去不复来。","朝看他人儿，暮看他人子。","一日一夜閒，十生九复死。","君不见昨夜人静黄昏时，含辛抱痛无人知。","其时忽不记儿死，倚门引颈望儿归。"]},{"t":"客去","f":"五言律诗","c":["客去即吟诗，吟诗即饮酒。","时时进一杯，往往积成斗。","贪忆洛阳花，忘却江头柳。","借问别离客，得似寻常否。"]},{"t":"杨柳枝","f":"七言律诗","c":["杨柳杨柳复杨柳，舞罢青衫困垂手。","相如病思最多情，沈约才清更酣酒。","君看好鸟鸣枝閒，日与春风问安否。","清明前后峭寒时，好把香绵閒抖擞。"]},{"t":"睡 其一","f":"五言律诗","c":["睡入净域居，梦有殊方乐。","不须汎海装，去采神仙药。","手辟黄金阙，足踏巨鳌壳。","更作西方行，真到昆崙脚。"]},{"t":"睡 其二","f":"五言律诗","c":["人莫嗟劳生，睡者吾一乐。","困来入醉乡，梦去得仙药。","瘦胫鹤伸足，老背龟侧壳。","日出纸窗明，烟霞忽失脚。"]},{"t":"醉题友人诗后","f":"词","c":["可惜两眼青，不见一室白。","为子吟喉乾，使我酒面赤。","醉中一夜骑鸾凤，麻姑空敞桃花洞。","南楼下去北轩中，西关放过东皋梦。"]},{"t":"同门人夜看花示卢鲁山","f":"五言律诗","c":["罢酒已半夜，重来慰幽花。","可惜遭风雨，太半成泥沙。","移坐环其丛，含香嚼其华。","五人摘满手，归来千万葩。"]},{"t":"谢人惠梅花","f":"七言绝句","c":["江南费尽春风力，岭头驿使无消息。","有人赠我一枝花，满面春风与春色。"]},{"t":"代简招魏君","f":"七言绝句","c":["诗老今朝颇安否，且来同酌一杯酒。","虽无鼓吹相欢娱，自可笑吟相拍手。"]},{"t":"偶题","f":"词","c":["轺车使者良苦辛，手持汉节入红尘。","青嶂断时初见日，黄沙飞处不逢人。","妾身安在何足恤，红帘翠幕遮罗裙。","男儿大抵贵忠义，而况委质为人臣。","不忧死节奉王事，但恐偷生为妾身。","妾嫁郎时尚痴騃，可惜黄金如土卖。","误将玉体与儇儿，身卧污泥佩兰茝。","无礼无义将奈何，但抱罗衣千万带。","欲令高节比梁鸿，说与墦閒仍不改。","莫嗟远别离，离合良有时。","所愿君自爱，养取胸中奇。","莫恨别离久，愿君自持守。","所守义或非，得之适为丑。","君莫爱妾身，妾以死奉君。","一片玉为面，百尺布裁裙。","子亦当何如，为国爱其躯。","一节死不变，如妾事吾夫。","束带人待行，牵衣未能别。","遗子酒一卮，听我歌三阕。","其一献君寿，白发为君偶。","其二祝康宁，玉体和而平。","其三无累家，无令妾咨嗟。","不患不富贵，所患入于邪。"]},{"t":"三月三日作","f":"七言古诗","c":["今朝乃是三月三，三分春色二分去。","一分春色能几多，吟翁老病无如何。","却思翁在秦中时，年少爱游山与溪。","其时人物如神仙，手携酒榼擎花枝。","人不惜钱似痴騃，乞者与之见者买。","人人俱著好衣裳，处处纷纷成五采。","山上山前闹如市，人半归时城欲闭。","西溪最是柏坡头，人家占却无閒地。","更有几处入城早，清明上巳踏芳草。","若无疾病与死亡，人家大抵无烦恼。"]},{"t":"雁从何处来","f":"五言律诗","c":["雁从何处来，正望东南飞。","毛閒认白露，肚下看残晖。","浮云共烟水，日夜为所依。","衡阳是故山，但恐故人稀。"]},{"t":"金沙行","f":"楚辞体","c":["关西不雨凡几城，孜孜谁独劳其情。","镇潼太守真贤明，驱车远有金沙行。","春空破碧幢高旌，东风环佩锵瑶琼。","溪翁不钓童不耕，隆隆千里讴歌声。","从容祷罢残霞横，莲花顶上微云生。","云兮云兮云莫停，霈然一洒尘埃清。"]},{"t":"梦李白","f":"词","c":["乌纱巾，紫绮裘。","梦中太白从吾游，陶陶烂醉江山秋。","半夜起来觅不见，头背长安泪如霰。"]},{"t":"好笑南郭翁","f":"五言古诗","c":["好笑南郭翁，白鬓爱杨柳。","如今十月后，犹饮菊花酒。","杨柳色渍面，菊花香渍牙。","喉咙溜香汁，肠胃浮香葩。","所饮几何酒，所吟无限诗。","若言丝与管，便是吟哦时。","心无一事累，意与千古期。","一身成土木，两脚登云霓。","但欲比陶潜，岂肯为杜微。","公有如此客，可不使公知。","更问公安否，且喜公来归。"]},{"t":"观草 其一","f":"七言律诗","c":["一从有意惜庭芜，几日无心到杨柳。","好色尽归帘下翁，馀光掬与船中叟。","绀液难从日下乾，芳姿易向霜中老。","才到春还车马稀，青青胜却朱颜好。"]},{"t":"观草 其二","f":"七言律诗","c":["山前胜入樵儿手，亦胜江头伴烟柳。","閒中好步陶先生，醉里宜眠郑云叟。","我辟閒阶恨不早，草正茸茸花又老。","人心好恶任不齐，但问青红阿谁好。"]},{"t":"观草 其三","f":"五言律诗","c":["观草亦有术，可使无涯际。","谁知帘下情，或有林閒味。","南郭虽如此，东皋亦何异。","便可弃衣冠，閒枕青云睡。"]},{"t":"绣屏戏呈思权","f":"七言古诗","c":["先生卧内花为屏，锦堆四面红云生。","珊瑚枕上三四更，半醒半醉魂梦惊。","安得仙葩千万英，不是天台是武陵。"]},{"t":"与熊熊作策写诗","f":"五言古诗","c":["此是熊熊策，先题吴季诗。","季自题学书，如此怜吾儿。","季有古人风，怜儿心可知。"]},{"t":"莫望草","f":"五言律诗","c":["莫望坡头日，日色催行人。","莫望河上草，草色空连云。","云边芳草路，茫然是何处。","行人望不见，草色自如故。"]},{"t":"书乐陵王伯年太子传","f":"词","c":["酷哉武成，枉杀乐陵。","一步一杖，绕堂土赪。","投之池中，池水尽赤。","其妃哀号，至死不食。","其指其手，拳不可擘。","九院之后，小尸犹在。","骨碎肉烂，绯袍金带。","一袍有靴，一髻有解。","哀哉呜呼，此儿何罪。","贼人之孤，负人之托。","毒如豺狼，险如溪壑。","身自为孽，其子受之。","扼咽蒙头，连颈横尸。","报应如此，其来勿问。","与其自杀，不容尺寸。","我哀其愚，作为此诗。","永贻厥鉴，勿为险欺。"]},{"t":"哭崔刑部","f":"楚辞体","c":["前年离长安，与公为死诀。","长安门外长乐坡，胸中壮气浑消磨。","其时夜宿灞桥上，梦中勒马犹西望。","江淮之上情愈劳，去年曾寄西山高。","今年今日春将归，春风不似秋风时。","山阳数月雨不止，泥深穷巷行人稀。","忽闻公死终南山，坐中忽过东西关。","黄泉一去几万里，吁嗟公兮何时还。","盂有水兮无食荐，烹有茶兮无酒奠。","魂兮来兮不可知，来若飘风去如电。","报恩之事终有期，未必儒生只贫贱。"]},{"t":"哭狗狗","f":"楚辞体","c":["东门园上春风微，醇醇冢上花成围。","醇醇一去不复返，食一盂兮酒一卮。","悲莫悲乎今日，伤莫伤乎旧衣。","思其言而想其貌，吁嗟乎天殇吾儿。"]},{"t":"偶述","f":"五言律诗","c":["樽中一勺水，其味诚淡薄。","尽日设重席，无人与酬酢。","东邻有旨酒，金壶而玉爵。","门前罗轩车，陶陶一何乐。"]},{"t":"闵灾词","f":"楚辞体","c":["神地出渊泉，商羊向天舞。","电火烧黑空，雷车震金鼓。","大块噫风吹黄沙，黄沙须臾化为雾。","此时阴气一何盛，蚓嘘云兮鬼啸雨。","雨绳绳兮云蒸蒸，天惨惨兮朝复莫。","嗟尔长淮之民，何生而苦。","方馑而饥，方疫而愈。","乃有此患，普及于汝。","地涌水泉，天降淫雨。","浩浩之势，包山逾阜。","汝居无庐，汝耕无土。","汝口嗷嗷，其谁安诉。","吾闻尧水凡九年，民虽昏垫不失所。","愿我君王发德音，一变悲号作歌舞。"]},{"t":"复古颂","f":"词","c":["其难其难，道亦大艰，或缺或完。","战国盗窃，嬴秦暴孽，遗风馀烈。","所存几何，枯株之柯，填源之波。","汉得天下，方有学者，其徒盖寡。","孝文孝武，稍稍复古。","仲舒之伍，巉岩峥嵘。","穷先王经，道乃大明。","西汉之风，与三代同，实儒之功。","晋魏寇雠，学者寖浮，不源而流。","齐梁之閒，斧斫刀剜，大朴益残。","隋唱唐和，元气尽破，为斯文祸。","学者皇皇，赋道大光，六经逃藏。","冶容艳肤，绣衣红襦。","众奔群趋，若大有为。","谓之背驰，终身寒饥。","物不终盛，皇帝有命，万口齐庆。","复明经科，大张网罗，海隅山阿。","麟之奔奔，凤之轩轩，龙之蜿蜿。","会稽之竹，昆崙之玉，牛山之木。","逢蒙执射，伯乐进马，造父御驾。","琴瑟既更，韶音游声，复还于今。","唐虞之谟，夏商之书，其庶几乎。","天下之赋，摧缩消沮，迷失道路。","革万世弊，兴万世利，繄我皇帝。","臣敢不歌，流为大和，百世不磨。"]},{"t":"暴雨","f":"词","c":["玉女投壶天大笑，千寻火炬当空照。","老龙行迟天忽怒，雷车壮士?连鼓。","黑鳞铁甲十万许，急把银河倾作雨。"]},{"t":"思诚斋夜坐","f":"五言绝句","c":["胸中不平气，忽然凌太虚。","无人哭一声，半夜思唐衢。"]},{"t":"逃席","f":"五言律诗","c":["主人虽好事，其来不知几。","胡不筑高垣，胡不关重扉。","不敢直道退，遂由邪径归。","饮过即有疾，何以慰亲闱。"]},{"t":"有客何为者","f":"五言律诗","c":["有客何为者，不穿亦不凿。","匣中是何物，尘埃渍锋锷。","登山守直道，荆榛与沟壑。","安得百亩田，以就斑衣乐。"]},{"t":"周长官出二子诗相示","f":"七言律诗","c":["丹山一凤双雏生，十分羽翼三分成。","未能飞奋先能鸣，才鸣不作凡鸟声。","羽毛安得相混并，鹏霄九万当冥冥。","箫韶九奏仪王庭，光华舜旦魁群经。"]},{"t":"又赠二子","f":"七言古诗","c":["周氏二子千人英，余观其诗余辄惊。","浑然骨格已老成，凛乎辞句冰霜清。","不然何以知君名，余知必作诗之精。","今观君诗眉且低，文章老大无人知。","少年便莫相轻欺，丈夫壮气如虹蜺。","古之庸者犹雄飞，青云自有相逢时。"]},{"t":"封本堂","f":"词","c":["物无其实，其名弗至。","实以先之，名以次之。","事无其实，君子弗名。","可表其实，可考其行。","名以表之，行以考之。","信斯名者，斯民可见。","乐斯名者，斯堂可燕。","可燕可歌，使臣之光。","有孚实惠，民悦无疆。"]},{"t":"书江氏芝草记后","f":"词","c":["天门嶪嶪，洞达通彻。","地虽幽阴，明白昭晰。","有来即应，无往弗答。","或旋其日，或逾厥月。","或降吉祥，或出妖孽。","或生美好，或产丑缺。","或使合并，或令分裂。","凡皆若此，其故可说。","人之所喜，神则欢悦。","和气流畅，精粹凝结。","草木受之，形类孤绝。","其无所苟，而不徒设。","爰有江氏，世载其德。","子子孙孙，能敬勿失。","其叔有令，如出诸意。","戮力同心，道路相继。","二十六丧，收敛聚会。","在圉之北，同日俱痤。","乃有二物，以彰厥美。","其一维何，是曰灵芝。","如盖上设，如杠下持。","其色黄紫，其光陆离。","其肉坚厚，弗柯弗衰。","其二维何，是曰连理。","巨干修枝，贯通骨髓。","物不可间，人不得披。","以类考之，不必异本。","其奇若此，其吉勿问。","其恍其惚，其惚其恍。","必寓诸物，以来神贶。","维神之贶，如冈如陵。","有德者胜，德虽可胜。","其心兢兢，则亦可承。","维神之贶，必以其类。","或大其家，或大其世。","敬之戒之，永终厥义。"]},{"t":"新安吕公尚书夫人坟","f":"词","c":["彼美新安，有水有山。","有坟岿然，百五十年。","爰有曾孙，赤韨朱轩。","来守兹土，以慰斯坟。","扫除必躬，奉祠必亲。","水毛陆产，膋牲上尊。","百物皆具，千兵骏奔。","观者如堵，从者如云。","心追无穷，诚通无垠。","溟漠之魄，恍惚之魂。","如辟其涂，如启其门。","如兴于寝，如作于室。","如出黄泉，如见白日。"]},{"t":"谢秀才晦庵","f":"词","c":["山有武夷，水有建溪。","有猿有鹤，有庵可栖。","有庵可栖，云乎不归。"]},{"t":"哀吟赠蔡子骧女","f":"词","c":["蔡氏之子，彼仲女者。","考之古今，如仲者寡。","有德之容，有德之性。","所好所习，一出于正。","貌庄而丽，气温而醇。","女子之中，而有斯人。","慈良端厚，内敏而重。","终日寡言，亦不戏弄。","字无难易，所见辄识。","不知此女，从何而得。","读释氏书，欣然有适。","身之所有，皆出自然。","如何不幸，不假之年。","扬州道中，死于六月。","二十七日，暑气酷烈。","二十九日，三更大殓。","形神如生，体亦不变。","其气甚洁，其香甚郁。","附于身者，何用珠玉。","不知此女，而往何处。","杳杳冥冥，云霞烟雾。","世之所有，则维其常。","若斯人者，独秀孤芳。","吾于其母，是为内兄。","哀吟恻恻，慰其死生。"]},{"t":"题淮阴泰山行宫庙","f":"词","c":["泰山隆隆，作镇于东。","有如配林，在淮之阴。","厥庙维严，厥貌维肖。","斯民奉之，是为别庙。"]},{"t":"登淮阴古城","f":"七言绝句","c":["此城不可名甘罗，淮阴侯国冤忿多。","其气郁郁而勃勃，遂令平地生嵯峨。"]},{"t":"爱爱歌","f":"楚辞体","c":["吴越佳人古云好，破家亡国可胜道。","昨夜閒观爱爱歌，坐中叹息无如何。","爱爱乃是娼家女，浑金璞玉埋尘土。","歌舞吴中第一人，绿发双鬟才十五。","耳闻眼见是何事，不谓其人乃如许。","操心危兮虑患深，半夜灯前泪如雨。","假如一笑得千金，不如嫁作良人妇。","桃李不为当路花，芙蓉开向秋风渚。","忽然一日逢张氏，便约终身不相弃。","山可磨兮海可枯，生唯一兮死无二。","有如樗栎丛中木，忽然化作潇湘竹。","又如黄鸟春风时，迁乔木兮出幽谷。","文君走马来成都，弄玉吹箫才几曲。","不闻马上琵琶声，却在山头望夫哭。","去年春风还满房，昨夜月明还满床。","行人一去不复返，不是江山歧路长。","前年犹惜金缕衣，去年不画深燕脂。","今年今日万事已，鲛绡翡翠看如泥。","一女二夫兮妾之所羞，不忠于所事兮其将何求。","蛾眉皓齿兮乃妾之雠，不如无生兮庶几无尤。","喓喓草虫兮趯趯阜螽，靡不有初兮鲜克有终。","鸳鸯于飞兮毕之罗之，人閒此恨兮消何时。","深山人迹不到处，病鸾敛翅巢空枝。"]},{"t":"一般花下饮一盏","f":"七言绝句","c":["一般花下饮一盏，但是花开不须拣。","乱红乱翠已迷人，犹望桃源回醉眼。"]},{"t":"题寄亭","f":"楚辞体","c":["大抵人閒同一寓，外物之来寓中寓。","主人于尔本无心，谁使之来谁使去。","来时无所增吾悦，去时谈笑亦不辍。","惟有山叟与溪翁，屋里閒云船上月。","一从古往成蹉跎，失之则憾得之歌。","不从平路从风波，或遭陷阱或网罗。","有人啮臂遗其亲，有人之楚复之秦。","侯门洒扫宁苦辛，牛衣涕泣伤贱贫。","谁人衒鬻来上书，谁人乞贷留公车。","谁人入关便弃繻，谁思躣马疾其驱。","更有隋时二隐夫，欲将林壑谋金朱。","倒行之辈尤可吁，当时自欲烹其躯。","却是扬雄所性恬，谁须名字学韦贤。","积薪可恨汲生言，不道真风任自然。","自然处者其为谁，以寄名亭如此奇。","俗人所患在失之，安知达者静者心平夷。","达者洞然无所蔽，静者泊然无所累。","无蔽无累无所营，其中主者性与诚。","登斯亭兮观斯名，人閒万事皆可平。"]},{"t":"耳边啼鸟唤不起","f":"七言绝句","c":["耳边啼鸟唤不起，有人醉卧春风里。","被花迷入梦魂中，却上烟霞弄瑶水。"]},{"t":"偶述","f":"七言绝句","c":["淮阴寄食卒为将，南阳閒卧卒为相。","孟轲之道其如何，枉尺如何直寻丈。"]},{"t":"有客不为赋","f":"词","c":["有客不为赋，而乃求荣阶。","是犹适吴楚，却背东西来。","孟郊从进士，闻者徒相咍。","退之发已秃，知己其谁哉。","余独谓不然，此事何足哀。","但恐子之道，未足为奇侅。","子歌坚诚好，不为利所回。","得则为颜氏，失则为隤懒。","为子歌一阕，为子酌一杯。","余歌为尔宜何歌，余闻日月如飞梭。","但忧其道不到古，穷通之事余如何。"]},{"t":"八月十四夜","f":"七言古诗","c":["有人望月吟太虚，半夜秋风生碧芦。","碧芦风起吹老桂，吟声入月惊蟾蜍。","明夜中秋更好吟，兔肥蟾大桂成林。","桂兔之外有何物，玉池水到中秋溢，秋风刮水如霜滴。"]},{"t":"中秋月下作赠吕秘校","f":"五言律诗","c":["去年中秋月，与子共吟诗。","今年中秋月，与子嗟别离。","前书约相见，颇说中秋期。","夜久风霜寒，对月空相思。"]},{"t":"寄汝弼","f":"五言律诗","c":["山阳如许大，不与我同住。","翩翩雁与鸿，可惜分飞去。","淮中极清泚，亦有洲与沚。","一雁自安栖，一鸿望江水。"]},{"t":"寄张宜伯","f":"七言律诗","c":["空中气候何苍苍，风力不劲云不黄。","一冬无雪农家忙，为忧麰麦不丰穰。","若有雪时满引觞，仍将诗去报庾郎。","牢收浙帅厨中羊，恐有剑客过城隍。"]},{"t":"渔者","f":"七言古诗","c":["缚竹编茅杂乱蓬，四篱俱是野花丛。","莫道江湖山色好，篱落不禁秋后风。","秋后风从西北起，身上蓑衣冷如水。","夫妻却在钓船中，儿孙走入芦花里。","夫妻不会作活计，辛苦卖鱼沽酒费。","儿孙身上更贫穷，白日无衣夜无被。","昨日前村酤酒处，今朝忽见无人住。","闻道江南地更暖，移舟急望江南去。"]},{"t":"钓者","f":"七言绝句","c":["有人口诵浮云曲，手把潇湘一竿竹。","荻花洲上作茅庵，坐看江头浪如屋。"]},{"t":"渔翁","f":"七言绝句","c":["白发老翁心似铁，网尽溪鱼犹未歇。","船中浑是卖鱼钱，买酒烹鱼醉明月。"]},{"t":"濉阳","f":"五言古诗","c":["尝闻唐李氏，世号为贤妻。","以力营七丧，或谓难庶几。","孰知蔡家妇，其事乃同之。","岂特在中馈，无往而无仪。","孝于其所尊，慈于其所卑。","即知义所在，能终义所为。","我生至此极，我嫁逢百罹。","其属死略尽，其骨俱无归。","身为未亡人，心乃真男儿。","以己任其责，无忘须臾时。","但恐事不济，安知恤寒饥。","乃捐奉生具，而为送亡资。","面不御膏沐，首不加冠笄。","金珠鬻于市，文绣容何施。","更无囊中装，唯有身上衣。","殆将截其发，幸苟完其肌。","所得盖良苦，所积从细微。","如此十年久，犹以为支离。","日下卜诸良，宅兆相厥宜。","一举十八丧，一旦得所依。","手自植松楸，身亦沾涂泥。","何暇裹两足，但知勤四肢。","居者叹于室，行者泣于歧。","鸟亦助叫号，人思操蔂梩。","冥冥长夜魂，所获喜可知。","郁郁佳城中，不为中道尸。","卒办其家事，少慰而心悲。","义深海可涸，行坚山可摧。","孤诚贯白日，幽光淩虹霓。","吾闻古烈女，荦荦非无奇。","一死盖易处，一节亦易持。","至如张氏者，使人尤歔欷。","谁为孝妇传，谁为黄绢碑。","亦有淮上翁，为述濉阳诗。","移书太史氏，无令兹逸遗。"]},{"t":"临卧","f":"七言绝句","c":["临卧更饮一杯酒，自唱仙谣拍双手。","春风欺醉入怀来，留下乱花香一斗。"]},{"t":"哀哀词","f":"词","c":["哀哀复哀哀，哀哀至此极。","孤儿与慈母，中路忽相失。","恍惚须臾閒，终日不复得。","谁复坐我堂，谁复入我室。","谁复饮儿酒，谁复哺儿食。","儿饥复谁念，儿寒复谁恤。","耳不闻慈语，目不见慈色。","譬如行路人，日远如一日。","行人犹可期，远道犹可追。","天穷地尽处，一日犹可归。","哀哀复哀哀，此去无尽时。","谁言生离别，不知死别离。","君不见人已闭门鸟已栖，黄昏冢畔孤儿啼。"]},{"t":"李阳冰篆","f":"词","c":["书之有古篆，文之有六经。","秦汉而下浸以徙，隶学基路生重扃。","其閒述者亦世出，牛蹄之水才一泓。","先生之志在复古，胸中直气何森森。","独乘骐骥追大朴，执缚浮锐攘欃枪。","手中一笔千万变，天风号令驱雷霆。","蛇蟠蠖屈体既具，鹗立虎视势乃成。","刚柔伸屈有常势，天地之道阳与阴。","杰然出者其势耸，岳仞五千磨太清。","盘然屈者非一屈，黄河九折来沧溟。","庞然一画势自若，老将坚卧中军营。","至于一点亦有象，地丘人目天之星。","先生大体贵淳古，轻轻重重齐权衡。","周家太师负黼扆，高冠大旆朝王庭。","唐虞二帝正揖让，皋夔稷契环两楹。","圣人作乐有大本，剔抉淫卫完古音。","大匠作室以规矩，悉去臲?除斜撑。","专车骨节世不朽，今乃一纵而一横。","巨灵以手遏大难，印入山骨磨不平。","雄恢严毅不可犯，手中常握十万兵。","信乎创字自有说，宜必象形而象声。","天地之大有万象，万象不能遁其情。","呜呼篆法乃如此，大哉刚健纯粹精。","走兽之类为麒麟，飞鸟之类为鹪鹏。","蹊径之类为大路，垣墙之类为坚城。","以德论之为圣人，以法论之为朝廷。","傍睨众字乃可笑，太山之重鸿毛轻。","亡国之主好逸豫，儿女子辈多骄淫。","圣人之后惟孟子，古篆之后唯阳冰。","金浑玉璞天下宝，嗟乎世俗多聋盲。","欲行古道世辄笑，欲言古学世辄惊。","志之所之在一赋，斗筲之器徒易盈。","雕虫篆刻满天下，不矜实行矜虚名。","六经尘土塞高阁，圣人之道成坎坑。","况乎古篆固可弃，胡为独好于先生。"]},{"t":"吊屈平","f":"七言律诗","c":["洞庭湖口君须过，为我回头吊屈平。","楚国谁曾怜直道，湘江依旧寄冤声。","反骚义命贤扬子，作赋讥伤陋贾生。","若是独醒无不可，荷蓑犹可钓而耕。"]},{"t":"重阳日访马存秀才席上寄崔公太守","f":"七言律诗","c":["区区拖损一紬袍，行到郊居力已劳。","有命自知谁畏祸，无灾可避谩登高。","黄金菊满花情薄，白玉樽深酒兴豪。","尽日使君人不至，渊明吟醉也陶陶。"]},{"t":"哭彦规 其一","f":"七言律诗","c":["已矣哀哉死有终，青衫就木未为穷。","义如有枉荣斯辱，事苟无邪蹇胜通。","力致全丧关右帅，泣寻孤榇郭西翁。","精神入梦非生及，使我低颜愧古风。"]},{"t":"哭彦规 其二","f":"七言律诗","c":["初余视子发垂肩，及至成童便耸然。","忧患缠来成白颔，声名随去入黄泉。","孤甥见恤情非浅，暴骨收藏义可传。","多少文章零落尽，朝廷何处访遗编。"]},{"t":"哭彦规 其三","f":"七言律诗","c":["与君相得久忘言，晚更倾肠共豁然。","刬尽丘陵平作路，决开沟浍合为川。","古人刎颈终相杀，世俗操心爱胁肩。","六十老翁能有几，却寻旧友向黄泉。"]},{"t":"哭彦规 其四","f":"七言律诗","c":["有时半日两敲门，语罢南窗坐北轩。","意外得文哀绝笔，理中论事酷能言。","须知是物非无本，若论斯人自有源。","不蹈不袭真所性，洪河自古出昆崙。"]},{"t":"哭彦规 其五","f":"七言律诗","c":["青衫伴我情弥重，白首期君事忽乖。","天下若教俱好义，道傍安得有遗骸。","且将绵盖孤儿寝，谁折荆为稚女钗。","吟至此篇还索酒，更持姜桂坐寒斋。"]},{"t":"哭彦规 其六","f":"七言律诗","c":["我诵千涛喷雪诗，急提笔去写僧扉。","碧芦阴处评文坐，黄菊花时载酒随。","老丈为儿亲送药，衰翁赖子少呼医。","最是秦中葬枯骨，不须铭墓只镌肌。"]},{"t":"哭彦规 其七","f":"楚辞体","c":["道傍有无车马通，朝复莫兮秋且冬。","草头半折木已空，鸟啄噤兮霜与风。","白鸥肚上残日红，一丘莽苍黄昏中。","亦有松陵怨诗否，此时谁访谈玄翁。"]},{"t":"赠胡大夫","f":"七言律诗","c":["好读奇书好运筹，横刀常赋玉关秋。","铜符正选千兵守，金印犹虚万户侯。","艗趁潮来家易到，龙投池上剑难求。","应须读尽平蛮策，二广封疆近吉州。"]},{"t":"寄吕帅 其一","f":"七言律诗","c":["北边控扼重瀛州，虎视鹰扬属壮猷。","尽道胡人新断臂，安知汉将欲舂喉。","为文法度堆青简，奉使勋劳半白头。","六路全秦与全魏，不须野战觅封侯。"]},{"t":"寄吕帅 其二","f":"七言律诗","c":["师屯十万建牙旗，大纛森森重使威。","燕颔将军宜绣帽，龙骧战士爱犀衣。","银鎗作队行春去，蜡炬成林校猎归。","更看铃斋凭几处，文如布阵翰如飞。"]},{"t":"寄吕帅 其三","f":"七言律诗","c":["胡人勇悍真勍敌，汉将威名重泰山。","隐若金城当一面，横如铁阵控三关。","防秋甲士屯田去，牧马毡裘避塞还。","儒帅著书閒暇否，两淮人物太平閒。"]},{"t":"寄吕帅 其四","f":"七言律诗","c":["帅臣所统在燕南，事事如窥指掌閒。","仗钺精神堪破虏，扼吭形势正当关。","十洲部分连沧海，一道军声过黑山。","文武非徒尹吉甫，前时方叔已平蛮。"]},{"t":"寄吕帅 其五","f":"七言律诗","c":["事皆术内宜谋帅，奇在胸中合运筹。","战士常骑突阵马，将军须养犒师牛。","雅歌坐燕春归塞，缓带行吟月上楼。","且劝主人宜饮酒，边城六月已如秋。"]},{"t":"赠刘懋功","f":"七言律诗","c":["李令归来岁月深，池人得子贵其情。","定知县事依前简，还记官曹复旧清。","如问以思谋所贵，能严而恕罚斯轻。","芙蓉水上人相忆，因寄梅花附此声。"]},{"t":"赠汪判官","f":"七言律诗","c":["庾郎酝藉本仙材，适自王家池上回。","杨柳风前红蜡炬，芙蓉香畔白髯腮。","便摇健笔挥诗藁，仍替衰翁倒酒罍。","说与泗州倪发句，梦随淮水向东来。"]},{"t":"赠刘閤使","f":"七言律诗","c":["荦荦雄名骇世閒，堂堂谁敢举头看。","高谈豹略今无敌，谁污龙泉血未乾。","蛮贡急趋金殿肃，胡蹝深入铁山閒。","关中自号诗书将，肯愧齐王在将坛。"]},{"t":"寄路倅","f":"七言律诗","c":["此中可恨恨无山，犹胜纷纷富贵閒。","绿野尽充公好尚，朱门安得水回环。","对云披住云边浪，踏月空行月下湾。","好戴宫纱著宫锦，时时吟去复吟还。"]},{"t":"和范君锡观梅 其一","f":"七言律诗","c":["君看梅艳似何人，不画蛾眉色自真。","冷寄北风淮上雪，暖思南国岭头春。","莫嗔俗眼偏相弃，若比夭桃太不匀。","我共参军同所好，折来酣笑插乌巾。"]},{"t":"和范君锡观梅 其二","f":"七言律诗","c":["月庭有影终难辨，雪径无香不易分。","江上肌肤新出浴，岭头环佩忽藏云。","少他几幅青罗袂，解与何人绣段裙。","我爱此花真一色，将诗急报范参军。"]},{"t":"和吕秘校观梅 其一","f":"五言古诗","c":["若论君颜色，琼瑶未足珍。","花中谁作偶，物外独先春。","有艳皆归朴，无妖可媚人。","江南看已厌，洛浦种还新。","日晚巫山雨，墙低宋玉邻。","施朱其已伪，傅粉亦非真。","堪把歌诗赠，何辞唱和频。","君篇为第一，便可献枫宸。"]},{"t":"和吕秘校观梅 其二","f":"五言古诗","c":["寒梅虽淡薄，乃是物之珍。","天与离群性，花前独步春。","江皋多冒雪，山路不逢人。","根本蟠虽久，花趺长自新。","妖姿虽共处，正色愿相邻。","纵使红为饰，何如素是真。","北人殊未识，南国见何频。","须假东风力，春香到紫宸。"]},{"t":"寄顾瀛州","f":"七言律诗","c":["本朝谋帅得雄刚，气语无邪面目方。","掌握事严持斧钺，咽喉地紧扼豺狼。","铁林猛士新翻阵，幕府奇书旧满囊。","可减边兵三十万，匈奴走入黑山藏。"]},{"t":"送倪敦复 其一","f":"七言律诗","c":["手持报简人归后，足步回廊角住声。","但恐舟行随早晚，此时秋色半阴晴。","明朝路向云边望，今夜诗须枕上成。","四壁无灯窗有月，直无老梦到三更。"]},{"t":"送倪敦复 其二","f":"七言律诗","c":["连朝送客经三日，每夜忘眠约数更。","枕上寻船无梦去，窗间望月有诗成。","莫愁病叟添愁思，为恐行人趁晓晴。","急送村醪追后乘，要教饮处忆南城。"]},{"t":"送倪敦复 其三","f":"七言律诗","c":["各自逢人且寄音，仍须南北梦相寻。","已成凫雁分飞势，更值淮湖连日阴。","每论事时于义切，重来别后此情深。","山东定饮登高酒，剩折黄花望我吟。"]},{"t":"寄吕海州","f":"七言律诗","c":["朱轮海上新迎部，玉笋朝中旧立班。","曾屈高风来泮水，宜将老梦到朐山。","霞张列炬红弥野，潮作飞霜白叩关。","三四百州为第一，日华先照郡楼閒。"]},{"t":"赠至几 其一","f":"七言律诗","c":["淮东学士求新范，海角仙人弃旧居。","不用更携扬子酝，但来同啖庾郎蔬。","赤墀待把文章献，黄绶难亲议论馀。","泮水宫中方就讲，何烦留下橐中书。"]},{"t":"赠至几 其二","f":"七言律诗","c":["西城塔下逢君后，南郭庠中借馆居。","正共孤甥栖暖席，未如老圃灌寒蔬。","直生岂敢嗟年暮，饿死犹惭乞祭馀。","六十衰翁如可教，更忙须遗所藏书。"]},{"t":"赠至几 其三","f":"七言律诗","c":["僧房几载如禅定，州序今来以义居。","直道褐衣犹胜锦，枉身牢鼎不如蔬。","何心敢冀浆先馈，无善兼令岁有馀。","最是学文方自讼，只堪把笔教儿书。"]},{"t":"赠至几 其四","f":"七言律诗","c":["南州本是诸儒秀，上国宜从大隐居。","别我好留仙竹杖，送君欲献野芹蔬。","所惭下士文章陋，未报诸公礼义馀。","若见汝阴前太守，为言迂阔正谈书。"]},{"t":"赠至几 其五","f":"七言律诗","c":["谁家门外柳双株，满屋清风是我居。","霜后正逢篱下菊，雪前已贮瓮中蔬。","沫流口角耽吟睡，毛坠头心久病馀。","努力正如初学辈，老瞳昏涩夜看书。"]},{"t":"复明经","f":"五言古诗","c":["上欲求稽古，天书下四溟。","儒风久湮郁，诏意乃丁宁。","削剥因唐氏，源流自汉庭。","春秋披日月，易象炳丹青。","礼乐搜潜奥，诗书抉杳冥。","今焉拘注疏，何谓复明经。"]},{"t":"和蒋龙图","f":"七言律诗","c":["吟翁如共老庄游，物外能齐乐与忧。","鳌背不为三岛客，鱼竿终泛五湖舟。","何须大使诗来问，合使幽人病为瘳。","陶令菊花犹有在，未知肯饮一杯不。"]},{"t":"送吕清叔 其一","f":"七言绝句","c":["人为多情乃送君，余虽不送情更深。","破窗半夜风霜冷，危坐灯前为子吟。"]},{"t":"送吕清叔 其二","f":"七言绝句","c":["平生志在青云霄，十年不飞藏羽毛。","夫子乃是知我者，吟诗赠子何辞劳。"]},{"t":"送吕清叔 其三","f":"七言绝句","c":["匆匆一棹向东行，抖擞空囊无一金。","买鱼沽酒向村市，典却蔡家焦尾琴。"]},{"t":"送吕清叔 其四","f":"七言绝句","c":["深院吟哦夜半时，须有鬼神听此诗。","吟声往往到明月，淮上有风摇桂枝。"]},{"t":"和蒋颖叔 其一","f":"七言律诗","c":["城外人传大使来，吟翁正共客衔杯。","赤帷便记长安道，骏马仍思御史台。","义色可令奸胆破，刚姿不为疾风摧。","公能几日山阳住，待报舟人且倒桅。"]},{"t":"和蒋颖叔 其二","f":"七言律诗","c":["盛德尊光不召宾，玉环星弁自迂身。","北窗卧者陶元亮，大使车中陆子真。","自道老来心逾壮，若论兵后气弥真。","所惭旧学非精义，仰负高风如古人。"]},{"t":"送人之洛阳","f":"七言绝句","c":["待到伊川濯尽尘，洛阳城下且留身。","文才得似长沙傅，试问如今有几人。"]},{"t":"寄苏子由","f":"五言律诗","c":["午日移阴后，行人罢燕时。","路从西郭去，船值北风吹。","梦里犹回首，心中欲附诗。","从来义如此，两意自相知。"]},{"t":"赠慎叔良","f":"五言律诗","c":["我是东皋叟，君居在屋东。","已曾同砚席，最好共耕农。","蕙帐兼栖鹤，篮舆亦带筇。","若评樵采事，须更唤邻翁。"]},{"t":"寄田大夫","f":"五言律诗","c":["老掾成迂阔，弥年信不通。","白头负高义，病眼想清风。","奉使更三节，题名在两宫。","有人能举类，旧德起淮东。"]},{"t":"寄慎朝奉","f":"五言律诗","c":["一别三千里，俱为六十翁。","日中多俗事，枕上忆清风。","闻子生双凤，看书快两瞳。","以囊仍贮果，寄我厥苞红。"]},{"t":"寄张景修","f":"五言律诗","c":["东南未回客，行乐又经年。","吴市花朝酒，松江月夜船。","穷阎无屋住，广殿有诗传。","若论平生事，无如任自然。"]},{"t":"寄朱博士","f":"五言律诗","c":["吴有朱夫子，相知凡几年。","心怜闭门叟，书附过江船。","行已为人表，文应许世传。","临风有馀诲，时复慰皤然。"]},{"t":"和李闳中","f":"五言律诗","c":["幕官真有道，野叟是何人。","被此新诗赠，兼之古意醇。","若论今古事，前是老农身。","谁谓芙蓉客，能来相顾频。"]}]};